  min-width: 0;
  font: 650 11px/1.35 var(--jpdb-reader-font);
  text-align: center;
}

.jpdb-reader-newtab-support-copy strong {
  font-weight: 700;
}

.jpdb-reader-newtab-support-copy span {
  color: var(--jpdb-reader-muted);
}

.jpdb-reader-newtab-support-breakdown {
  color: var(--jpdb-reader-accent);
