  gap: 9px;
  min-width: 0;
}

.jpdb-reader-newtab-search-section h2 {
  margin: 0;
  color: var(--jpdb-reader-muted);
  font-size: 11px;
  font-weight: 860;
  line-height: 1.1;
  text-transform: uppercase;
}

.jpdb-reader-newtab-search-list,
.jpdb-reader-newtab-search-kanji-grid {
