  gap: 8px;
  min-width: 0;
}

.jpdb-reader-newtab-search-kanji-grid {
  grid-template-columns: repeat(auto-fit, minmax(168px, 1fr));
  align-items: start;
}

.jpdb-reader-newtab-search-kanji-grid
