  grid-column: 1 / -1;
}

.jpdb-reader-newtab-search-card-shell {
  min-width: 0;
  display: grid;
  gap: 0;
}

.jpdb-reader-newtab-search-card {
  width: 100%;
  min-width: 0;
  min-height: 68px;
  display: grid;
  align-content: center;
  justify-items: start;
  gap: 4px;
  padding: 12px 14px;
  border: 1px solid var(--jpdb-reader-border);
  border-radius: 8px;
  background: color-mix(
    in srgb,
    var(--jpdb-reader-surface) 82%,
    transparent
  );
  color: var(--jpdb-reader-text);
  text-align: start;
  cursor: pointer;
}

.jpdb-reader-newtab-search-card[aria-expanded="true"] {
  border-color: color-mix(
    in srgb,
    var(--jpdb-reader-accent) 62%,
    var(--jpdb-reader-border)
  );
  border-bottom-right-radius: 0;
  border-bottom-left-radius: 0;
}

.jpdb-reader-newtab-search-kanji-card {
  grid-template-columns: auto minmax(0, 1fr);
  grid-template-rows: auto auto;
  align-items: center;
  align-content: center;
  column-gap: 10px;
  row-gap: 3px;
  min-height: 58px;
  padding: 9px 11px;
}

.jpdb-reader-newtab-search-detail {
  min-width: 0;
  display: grid;
  justify-items: stretch;
  gap: 10px;
  padding: 12px;
  border: 1px solid var(--jpdb-reader-border);
  border-top: 0;
  border-radius: 0 0 8px 8px;
  background: color-mix(
    in srgb,
    var(--jpdb-reader-bg) 72%,
    var(--jpdb-reader-surface) 28%
  );
  text-align: start;
}

.jpdb-reader-newtab-search-detail
  :is(
    .jpdb-reader-header,
    .jpdb-reader-heading,
    .jpdb-reader-spelling,
    .jpdb-reader-meaning,
    .jpdb-reader-local,
    .jpdb-reader-source-card,
    .jpdb-reader-local-title,
    .jpdb-reader-local-head,
    .jpdb-reader-local-glossary
  ) {
  justify-items: stretch;
  text-align: start;
}

.jpdb-reader-newtab-search-detail
  :is(.jpdb-reader-title-row, .jpdb-reader-card-tools) {
  justify-content: flex-start;
}

.jpdb-reader-newtab-search-detail[hidden] {
  display: none;
}

.jpdb-reader-newtab-search-inline-kanji {
  display: grid;
  gap: 0;
  min-width: 0;
}

.jpdb-reader-newtab-search-inline-kanji .jpdb-reader-newtab-kanji-details {
  width: 100%;
  margin: 0;
  justify-self: stretch;
}

.jpdb-reader-newtab-search-detail > .jpdb-reader-newtab-kanji-details {
  width: 100%;
  margin: 0;
  justify-self: stretch;
}

.jpdb-reader-newtab-search-kanji-item {
  display: grid;
  gap: 0;
  min-width: 0;
  padding-top: 12px;
  border-top: 1px solid
    color-mix(in srgb, var(--jpdb-reader-border) 72%, transparent);
}

.jpdb-reader-newtab-search-kanji-item:first-of-type {
  padding-top: 0;
  border-top: 0;
}

.jpdb-reader-newtab-search-kanji-item + .jpdb-reader-newtab-search-kanji-item {
  margin-top: 14px;
}

.jpdb-reader-newtab-search-kanji-item-title {
  display: flex;
  align-items: baseline;
  gap: 8px;
  min-width: 0;
  padding-bottom: 8px;
  color: var(--jpdb-reader-text);
}

.jpdb-reader-newtab-search-kanji-item-char {
  flex: 0 0 auto;
  font-size: 26px;
  font-weight: 880;
  line-height: 1;
}

.jpdb-reader-newtab-search-kanji-item-keyword {
  min-width: 0;
  color: var(--jpdb-reader-muted);
  font-size: 12px;
  font-weight: 780;
  line-height: 1.2;
  overflow-wrap: anywhere;
}

.jpdb-reader-newtab-search-word {
  grid-template-columns: minmax(72px, max-content) minmax(0, 1fr);
  column-gap: 12px;
}

.jpdb-reader-newtab-search-term,
.jpdb-reader-newtab-search-kanji-char {
  min-width: 0;
  color: var(--jpdb-reader-text);
  font-weight: 880;
  line-height: 1.1;
  overflow-wrap: anywhere;
}

.jpdb-reader-newtab-search-term {
  grid-row: span 2;
  font-size: 22px;
}

.jpdb-reader-newtab-search-kanji-char {
  font-size: 44px;
}

.jpdb-reader-newtab-search-kanji-card .jpdb-reader-newtab-search-kanji-char {
  grid-row: 1 / span 2;
  font-size: 34px;
}

.jpdb-reader-newtab-search-kanji-card
  :is(.jpdb-reader-newtab-search-meaning, .jpdb-reader-newtab-search-meta) {
  min-width: 0;
}

.jpdb-reader-newtab-search-meta,
.jpdb-reader-newtab-search-meaning,
.jpdb-reader-newtab-search-message {
  min-width: 0;
  color: var(--jpdb-reader-muted);
  overflow-wrap: anywhere;
}

.jpdb-reader-newtab-search-meta {
  font-size: 11px;
  font-weight: 780;
  line-height: 1.25;
}

.jpdb-reader-newtab-search-meaning,
.jpdb-reader-newtab-search-message {
  font-size: 13px;
  font-weight: 650;
  line-height: 1.38;
}

.jpdb-reader-newtab-search-message {
  padding: 12px 0;
}

.jpdb-reader-newtab-study {
  --jpdb-reader-newtab-study-text: var(--jpdb-reader-text);
  --jpdb-reader-newtab-study-muted: var(--jpdb-reader-muted);
  width: 100%;
  min-height: 0;
  display: grid;
  grid-template-rows: auto auto 1fr auto;
  align-content: start;
  align-items: start;
  justify-items: center;
  gap: clamp(8px, 1.8vh, 16px);
  color: var(--jpdb-reader-newtab-study-text);
  cursor: pointer;
  user-select: none;
  /* UT-21: keep vertical scrolling native but own horizontal pans —
     without this iOS Safari claims the gesture and fires pointercancel
     before the swipe threshold, so swipe-to-grade never completed. */
  touch-action: pan-y;
  padding-top: clamp(16px, 3vh, 32px);
}

.jpdb-reader-newtab:not(.jpdb-reader-newtab-kanji-mode) .jpdb-reader-newtab-study {
  grid-template-rows: auto auto auto auto;
}

.jpdb-reader-newtab[data-study-surface="academy"] {
  --jpdb-reader-bg: var(--academy-paper, #f1ead9);
  --jpdb-reader-surface: color-mix(
    in srgb,
    var(--academy-paper, #f1ead9) 88%,
    white
  );
  --jpdb-reader-surface-2: color-mix(
    in srgb,
    var(--academy-paper, #f1ead9) 72%,
    var(--academy-paper-deep, #ddd0b7)
  );
  --jpdb-reader-text: var(--academy-paper-ink, #29271f);
  --jpdb-reader-muted: var(--academy-paper-muted, #655f51);
  --jpdb-reader-faint: color-mix(
    in srgb,
    var(--academy-paper-muted, #655f51) 68%,
    transparent
  );
  --jpdb-reader-border: color-mix(
    in srgb,
    var(--academy-paper-ink, #29271f) 22%,
    transparent
  );
  --jpdb-reader-accent: var(--academy-accent, #5ea780);
  --jpdb-reader-accent-readable: color-mix(
    in srgb,
    var(--academy-accent, #5ea780) 62%,
    var(--academy-paper-ink, #29271f)
  );
  --jpdb-reader-accent-text: var(--academy-paper-ink, #29271f);
  --jpdb-reader-selection-bg: #6d5149;
  --jpdb-reader-selection-text: #fffdf5;
  min-height: 0;
  overflow: visible;
  color: var(--jpdb-reader-text);
  color-scheme: light;
  background: transparent;
}

.jpdb-reader-newtab[data-study-surface="academy"] .jpdb-reader-newtab-shell {
  width: 100%;
  min-height: 0;
  gap: 12px;
