}

.jpdb-reader-newtab[data-study-surface="academy"] .jpdb-reader-newtab-study {
  padding-top: 8px;
}

.jpdb-reader-newtab[data-study-surface="academy"]
  :is(
    .jpdb-reader-newtab-brand,
    .jpdb-reader-newtab-theme-controls,
    .jpdb-reader-newtab-overflow,
    [data-newtab-session-clock-host]
  ) {
