  border-color: var(--jpdb-reader-border);
  background: color-mix(
    in srgb,
    var(--jpdb-reader-surface) 86%,
    var(--academy-paper, #f1ead9)
  );
  box-shadow: inset 0 1px 0 color-mix(in srgb, white 54%, transparent);
}

.jpdb-reader-newtab[data-study-surface="academy"]
  .jpdb-reader-newtab-controls
  button[data-newtab-action="reveal"] {
  border-color: color-mix(
    in srgb,
    var(--academy-accent, #5ea780) 72%,
    var(--jpdb-reader-border)
  );
  background: var(--academy-accent, #5ea780);
  color: var(--academy-paper-ink, #29271f);
}

.jpdb-reader-newtab[data-study-surface="academy"]
  .jpdb-reader-newtab-controls.jpdb-reader-newtab-grade-controls {
  position: sticky;
  left: auto;
  bottom: 8px;
  transform: none;
  width: min(100%, 860px);
}

.jpdb-reader-newtab-study-anki-card {
  grid-template-rows: auto auto auto auto;
  align-content: start;
  gap: clamp(12px, 2vh, 22px);
}

.jpdb-reader-newtab-study-anki-card .jpdb-reader-newtab-prompt-anki-card {
  align-self: start;
}

.jpdb-reader-newtab-revealed:not(.jpdb-reader-newtab-kanji-mode)
  .jpdb-reader-newtab-study {
  padding-bottom: 0;
}

.jpdb-reader-newtab-setup-mode .jpdb-reader-newtab-study {
  grid-template-rows: auto auto auto auto;
  align-content: center;
  gap: clamp(10px, 2vh, 18px);
  padding-bottom: clamp(42px, 9vh, 96px);
}

.jpdb-reader-newtab-setup-mode .jpdb-reader-newtab-answer {
  min-height: 0;
}

.jpdb-reader-newtab-setup-mode .jpdb-reader-newtab-reading {
  max-width: min(620px, 100%);
  font-size: clamp(20px, 3vw, 30px);
  line-height: 1.16;
}

.jpdb-reader-newtab-answer,
.jpdb-reader-newtab-meaning {
  cursor: auto;
  user-select: text;
}

.jpdb-reader-newtab-answer :is(button, a, summary),
.jpdb-reader-newtab-meaning :is(button, a, summary) {
  cursor: pointer;
}

.jpdb-reader-newtab-kanji-mode .jpdb-reader-newtab-study {
  grid-template-rows: auto auto 1fr auto;
  align-content: start;
  align-items: start;
  gap: clamp(14px, 2vh, 24px);
  padding-top: clamp(24px, 4vh, 48px);
  padding-bottom: clamp(64px, 9vh, 120px);
}

/* Before the reveal the doodle IS the answer: keep the draw prompt sitting
   directly on top of the canvas instead of letting the 1fr answer row stretch
   and float the grid far below its instruction. */

.jpdb-reader-newtab-kanji-mode:not(.jpdb-reader-newtab-revealed)
  .jpdb-reader-newtab-study {
  grid-template-rows: auto auto auto 1fr;
  gap: clamp(8px, 1.4vh, 16px);
  padding-top: clamp(16px, 3vh, 32px);
}

.jpdb-reader-newtab-recall-mode .jpdb-reader-newtab-study {
  grid-template-rows: auto auto auto auto;
  align-content: start;
  gap: clamp(12px, 2vh, 20px);
  padding-top: clamp(18px, 4vh, 44px);
  cursor: auto;
}

.jpdb-reader-newtab-revealed.jpdb-reader-newtab-kanji-mode
  .jpdb-reader-newtab-answer,
.jpdb-reader-newtab-revealed.jpdb-reader-newtab-kanji-mode
  .jpdb-reader-newtab-meaning {
  width: 100%;
  max-width: 100%;
  min-width: 0;
  justify-items: center;
}

.jpdb-reader-newtab-count,
.jpdb-reader-newtab-status {
  max-width: min(100%, 520px);
  color: var(--jpdb-reader-muted);
  font-size: 11px;
  line-height: 1.2;
  font-weight: 780;
  text-align: center;
}

.jpdb-reader-newtab-count {
  --jpdb-reader-newtab-session-progress: 0;
  width: min(420px, calc(100vw - 56px));
  min-height: 26px;
  display: grid;
  gap: 6px;
  align-content: center;
  justify-items: center;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: color-mix(in srgb, var(--jpdb-reader-text) 78%, var(--jpdb-reader-muted));
  box-shadow: none;
}

.jpdb-reader-newtab-count::before {
  content: "";
  display: block;
  width: 100%;
  height: 5px;
  border: 1px solid color-mix(in srgb, var(--jpdb-reader-border) 70%, transparent);
  border-radius: 999px;
  background:
    linear-gradient(
      90deg,
      var(--jpdb-reader-accent) calc(var(--jpdb-reader-newtab-session-progress) * 100%),
      color-mix(in srgb, var(--jpdb-reader-surface) 72%, var(--jpdb-reader-bg)) 0
    );
  box-shadow:
    0 0 0 1px color-mix(in srgb, var(--jpdb-reader-black) 24%, transparent),
    0 8px 20px color-mix(in srgb, var(--jpdb-reader-accent-soft) 58%, transparent);
}

.jpdb-reader-newtab-count[hidden] {
  display: none;
}

.jpdb-reader-newtab-study-steps {
  width: min(820px, calc(100vw - 40px));
  min-height: 28px;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 6px;
}

.jpdb-reader-newtab-study-steps[hidden],
.jpdb-reader-newtab-study-steps:empty {
  display: none;
}

.jpdb-reader-newtab-study-step {
  flex: 0 1 auto;
  height: 28px;
  min-width: 0;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 0 9px 0 6px;
  border: 1px solid color-mix(in srgb, var(--jpdb-reader-border) 82%, transparent);
  border-radius: 999px;
  background: color-mix(in srgb, var(--jpdb-reader-surface) 88%, transparent);
  color: color-mix(in srgb, var(--jpdb-reader-text) 78%, var(--jpdb-reader-muted));
  font: inherit;
  font-size: 11px;
  font-weight: 800;
  line-height: 1;
  white-space: nowrap;
  cursor: pointer;
}

.jpdb-reader-newtab-study-step-index {
  width: 18px;
  height: 18px;
  display: inline-grid;
  place-items: center;
  border-radius: 999px;
  background: color-mix(in srgb, var(--jpdb-reader-muted) 16%, transparent);
  color: inherit;
  font-size: 10px;
}

.jpdb-reader-newtab-study-step[data-active="true"] {
  border-color: color-mix(in srgb, var(--jpdb-reader-accent) 72%, var(--jpdb-reader-border));
  background: color-mix(in srgb, var(--jpdb-reader-accent-soft) 48%, var(--jpdb-reader-surface));
  color: var(--jpdb-reader-text);
}

.jpdb-reader-newtab-study-step[data-active="true"] .jpdb-reader-newtab-study-step-index {
  background: var(--jpdb-reader-accent);
  color: var(--jpdb-reader-accent-contrast, #ffffff);
}

@media (min-width: 641px) {
  .jpdb-reader-newtab:not(.jpdb-reader-newtab-search-mode, .jpdb-reader-newtab-stats-mode)
    .jpdb-reader-newtab-shell {
    width: min(1040px, calc(100vw - 40px));
    gap: 14px;
  }

  .jpdb-reader-newtab[data-study-surface="academy"]:not(.jpdb-reader-newtab-search-mode, .jpdb-reader-newtab-stats-mode)
    .jpdb-reader-newtab-shell {
    width: 100%;
    min-width: 0;
    max-width: 100%;
    grid-template-columns: minmax(0, 1fr);
  }

  .jpdb-reader-newtab:not(.jpdb-reader-newtab-search-mode, .jpdb-reader-newtab-stats-mode)
    .jpdb-reader-newtab-study {
    min-height: min(70dvh, 720px);
    padding: clamp(18px, 3vh, 30px) clamp(22px, 4vw, 54px) clamp(26px, 4vh, 42px);
    border: 1px solid color-mix(in srgb, var(--jpdb-reader-border) 82%, transparent);
    border-radius: 18px;
    background: color-mix(in srgb, var(--jpdb-reader-surface) 72%, var(--jpdb-reader-bg));
    box-shadow:
      inset 0 1px 0 color-mix(in srgb, var(--jpdb-reader-white) 4%, transparent),
      0 22px 60px color-mix(in srgb, var(--jpdb-reader-black) 16%, transparent);
  }

  .jpdb-reader-newtab-study-steps {
    flex-wrap: nowrap;
    gap: clamp(4px, 0.65vw, 7px);
  }

  .jpdb-reader-newtab-study-step {
    padding-inline: 6px 8px;
    gap: 5px;
  }

  .jpdb-reader-newtab:not(.jpdb-reader-newtab-kanji-mode)
    .jpdb-reader-newtab-study > .jpdb-reader-newtab-prompt {
    margin-top: clamp(14px, 4vh, 44px);
  }

  .jpdb-reader-newtab-study[data-newtab-study-step="type-word"] {
    cursor: auto;
  }

  .jpdb-reader-newtab-study[data-newtab-study-step="type-word"]
    > .jpdb-reader-newtab-prompt {
    max-width: min(840px, 100%);
    margin-top: clamp(10px, 2.4vh, 26px);
    font-size: clamp(1.9rem, 4.2vw, 3.45rem);
    line-height: 1.16;
  }

  .jpdb-reader-newtab-study[data-newtab-study-step="type-word"]
