    margin-top: 0;
    border: 1px solid color-mix(in srgb, var(--jpdb-reader-border) 76%, transparent);
    border-radius: 12px;
    background: color-mix(in srgb, var(--jpdb-reader-bg) 84%, transparent);
    box-shadow: 0 14px 34px color-mix(in srgb, var(--jpdb-reader-black) 22%, transparent);
    backdrop-filter: blur(14px);
  }
}

