  padding: 7px 8px;
}

.jpdb-reader-newtab-study-tour-body {
  min-width: 0;
  display: grid;
  gap: 8px;
}

.jpdb-reader-newtab-study-tour-intro {
  margin: 0;
  font-weight: 850;
}

.jpdb-reader-newtab-study-tour-list {
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 6px 10px;
  list-style: none;
}

.jpdb-reader-newtab-study-tour-step {
  min-width: 0;
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr);
  gap: 6px;
  align-items: start;
}

.jpdb-reader-newtab-study-tour-index {
  width: 18px;
  height: 18px;
  display: inline-grid;
  place-items: center;
  border-radius: 999px;
  background: color-mix(in srgb, var(--jpdb-reader-accent) 18%, transparent);
  color: var(--jpdb-reader-text);
  font-size: 10px;
  font-weight: 900;
  line-height: 1;
}

.jpdb-reader-newtab-study-tour-copy {
  min-width: 0;
  display: grid;
  gap: 1px;
}

.jpdb-reader-newtab-study-tour-label {
  overflow: hidden;
  color: var(--jpdb-reader-text);
  font-weight: 850;
  line-height: 1.15;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.jpdb-reader-newtab-study-tour-note {
  color: color-mix(in srgb, var(--jpdb-reader-text) 68%, var(--jpdb-reader-muted));
  font-size: 11px;
  font-weight: 650;
}

.jpdb-reader-newtab-study-availability {
  margin: 0;
  color: color-mix(in srgb, var(--jpdb-reader-text) 68%, var(--jpdb-reader-muted));
  font-size: 11px;
  font-weight: 650;
}

.jpdb-reader-newtab-study-tour-step[data-gradeable="true"] .jpdb-reader-newtab-study-tour-index {
  background: var(--jpdb-reader-accent);
  color: var(--jpdb-reader-accent-contrast, #ffffff);
}

@media (max-width: 520px) {
  .jpdb-reader-newtab-study-tour {
    width: min(420px, calc(100vw - 28px));
    flex-direction: column;
    align-items: stretch;
  }

  .jpdb-reader-newtab-study-tour-list {
    grid-template-columns: 1fr;
  }

  .jpdb-reader-newtab-study-tour button {
    align-self: flex-end;
  }
}

.jpdb-reader-newtab-count:empty {
  min-height: 0;
  padding: 0;
  border: 0;
  background: transparent;
  box-shadow: none;
}

.jpdb-reader-newtab-revealed:not(.jpdb-reader-newtab-kanji-mode)
  .jpdb-reader-newtab-count:empty {
  min-height: 34px;
  visibility: hidden;
}

button.jpdb-reader-newtab-status {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  max-width: min(360px, calc(100vw - 56px));
  min-height: 26px;
  padding: 5px 10px;
  border: 1px solid rgba(139, 160, 177, 0.24);
  border-radius: 999px;
  background: var(--jpdb-reader-surface);
  color: var(--jpdb-reader-text);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.05),
    0 8px 22px rgba(2, 6, 10, 0.34);
  cursor: pointer;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

button.jpdb-reader-newtab-status:not(:disabled) {
  border-color: color-mix(
    in srgb,
    var(--jpdb-reader-accent) 44%,
    var(--jpdb-reader-border)
  );
  background: linear-gradient(
    180deg,
    color-mix(
      in srgb,
      var(--jpdb-reader-surface-2) 72%,
      var(--jpdb-reader-accent) 10%
    ),
    color-mix(
      in srgb,
      var(--jpdb-reader-surface) 86%,
      var(--jpdb-reader-accent) 8%
    )
  );
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--jpdb-reader-white) 5%, transparent),
    0 8px 22px
      color-mix(in srgb, var(--jpdb-reader-accent) 12%, var(--jpdb-reader-shadow));
}

button.jpdb-reader-newtab-status:disabled {
  cursor: default;
}

button.jpdb-reader-newtab-status:disabled:not(:empty) {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  border-color: transparent;
  background: transparent;
  color: color-mix(in srgb, var(--jpdb-reader-muted) 86%, var(--jpdb-reader-text));
  box-shadow: none;
}

button.jpdb-reader-newtab-status:disabled:empty {
  display: none;
}

.jpdb-reader-newtab-source-select {
  width: auto;
  max-width: min(180px, calc(100vw - 72px));
  min-height: 28px;
  padding: 4px 28px 4px 10px;
  border: 1px solid color-mix(in srgb, var(--jpdb-reader-border) 76%, transparent);
  border-radius: 999px;
  background: color-mix(in srgb, var(--jpdb-reader-surface) 90%, transparent);
  color: var(--jpdb-reader-text);
  font: inherit;
  font-size: 11px;
  font-weight: 800;
  line-height: 1.2;
  cursor: pointer;
}

.jpdb-reader-newtab-source-select[hidden] {
  display: none;
}

/* Provider colour dot on the closed dropdown face (a select cannot host
   the status-light span, so the dot is a background gradient). */

.jpdb-reader-newtab-source-select[data-source] {
  --jpdb-reader-newtab-source-dot: var(--jpdb-reader-faint);
  padding-inline-start: 24px;
  background-image: radial-gradient(
    circle at 12px 50%,
    var(--jpdb-reader-newtab-source-dot) 0 3.5px,
    transparent 4.5px
  );
  background-repeat: no-repeat;
}

.jpdb-reader-newtab-source-select[data-source="jpdb"] {
  --jpdb-reader-newtab-source-dot: var(--jpdb-reader-accent);
}

.jpdb-reader-newtab-source-select[data-source="anki"] {
  --jpdb-reader-newtab-source-dot: var(--jpdb-reader-state-new-bright);
}

.jpdb-reader-newtab-source-select[data-source="bunpro"] {
  --jpdb-reader-newtab-source-dot: color-mix(
    in srgb,
    var(--jpdb-reader-danger) 78%,
    var(--jpdb-reader-accent)
  );
}

.jpdb-reader-newtab-source-select[data-source="yomu-local"] {
  --jpdb-reader-newtab-source-dot: color-mix(
    in srgb,
    var(--jpdb-reader-accent) 60%,
    var(--jpdb-reader-state-new-bright)
  );
}

.jpdb-reader-newtab-source-select:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--jpdb-reader-accent) 72%, transparent);
  outline-offset: 2px;
}

.jpdb-reader-newtab-status-light {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--jpdb-reader-faint);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--jpdb-reader-faint) 16%, transparent);
}

.jpdb-reader-newtab-status-light[data-source="jpdb"] {
  background: var(--jpdb-reader-accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--jpdb-reader-accent) 18%, transparent);
}

.jpdb-reader-newtab-status-light[data-source="jiten"] {
  background: var(--jpdb-reader-state-learning);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--jpdb-reader-state-learning) 18%, transparent);
}

.jpdb-reader-newtab-status-light[data-source="anki"] {
  background: var(--jpdb-reader-state-new-bright);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--jpdb-reader-state-new-bright) 18%, transparent);
}

.jpdb-reader-newtab-status-light[data-source="bunpro"] {
  background: color-mix(in srgb, var(--jpdb-reader-danger) 78%, var(--jpdb-reader-accent));
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--jpdb-reader-danger) 18%, transparent);
}

.jpdb-reader-newtab-status-light[data-source="yomu-local"] {
  background: color-mix(in srgb, var(--jpdb-reader-accent) 60%, var(--jpdb-reader-state-new-bright));
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--jpdb-reader-accent) 16%, transparent);
}

button.jpdb-reader-newtab-status:not(:disabled):hover {
  border-color: color-mix(
    in srgb,
    var(--jpdb-reader-accent) 64%,
    var(--jpdb-reader-border)
  );
  background: linear-gradient(
    180deg,
    color-mix(
      in srgb,
      var(--jpdb-reader-surface-2) 66%,
      var(--jpdb-reader-accent) 16%
    ),
    color-mix(
      in srgb,
      var(--jpdb-reader-surface) 82%,
      var(--jpdb-reader-accent) 12%
    )
  );
}

/* UT-21: the always-on review-mode edge glows lived here (accent green on
   both sides at opacity 0.2). They read as a stuck green swipe affordance,
   so the drag-gated red/green glows on .jpdb-reader-newtab::before/::after
   replace them. */

.jpdb-reader-newtab-prompt {
  max-width: min(100%, 720px);
  margin: 0;
  padding: 0 clamp(8px, 3vw, 22px);
  border: 0;
  border-radius: 0;
  background: transparent;
  color: var(--jpdb-reader-newtab-study-text);
  font-size: clamp(2.25rem, 7vw, 5.2rem);
  font-weight: 900;
  line-height: 1.06;
  text-align: center;
  overflow-wrap: anywhere;
  text-wrap: balance;
  text-shadow: 0 1px 2px var(--jpdb-reader-shadow-soft);
}

.jpdb-reader-newtab-prompt .jpdb-reader-word,
.jpdb-reader-newtab-reading .jpdb-reader-word,
.jpdb-reader-newtab-sentence .jpdb-reader-word {
  --jpdb-reader-word-color-source: currentColor;
  --jpdb-reader-word-accessible-color: currentColor;
  --jpdb-reader-word-decoration-source: transparent;
  --jpdb-reader-word-highlight-source: transparent;
  --jpdb-reader-word-highlight-paint: transparent;
  --jpdb-reader-word-accessible-highlight: transparent;
  --jpdb-reader-word-highlight-shadow-source: none;
  --jpdb-reader-word-underline-offset: 0.08em;
  --jpdb-reader-word-underline-thickness: 0.08em;
  color: inherit !important;
  background: transparent !important;
  background-image: none !important;
  box-shadow: none !important;
  border-radius: 0 !important;
  text-decoration: none !important;
  -webkit-text-fill-color: currentColor !important;
}

.jpdb-reader-newtab-prompt .jpdb-reader-newtab-listen-card {
  font-size: 14px;
  font-weight: 700;
  line-height: 1.25;
  text-shadow: none;
}

.jpdb-reader-newtab-prompt .jpdb-reader-newtab-listen-card button {
  font-size: 13px;
  font-weight: 760;
}

.jpdb-reader-newtab-prompt .jpdb-reader-word *,
.jpdb-reader-newtab-prompt .jpdb-reader-word::before,
.jpdb-reader-newtab-prompt .jpdb-reader-word::after,
.jpdb-reader-newtab-reading .jpdb-reader-word *,
.jpdb-reader-newtab-reading .jpdb-reader-word::before,
.jpdb-reader-newtab-reading .jpdb-reader-word::after,
.jpdb-reader-newtab-sentence .jpdb-reader-word *,
.jpdb-reader-newtab-sentence .jpdb-reader-word::before,
.jpdb-reader-newtab-sentence .jpdb-reader-word::after {
  color: inherit !important;
  background: transparent !important;
  box-shadow: none !important;
  border-color: transparent !important;
}

.jpdb-reader-newtab-prompt-anki-card {
  width: min(100%, 760px);
  max-width: min(100%, 760px);
  min-width: 0;
  min-height: 0;
  position: relative;
  display: grid;
  align-content: center;
  justify-items: center;
  gap: clamp(10px, 1.8vh, 18px);
  font-size: clamp(18px, 2.1vw, 26px);
  font-weight: 520;
  line-height: 1.45;
  text-align: center;
  text-shadow: none;
  text-wrap: wrap;
}

.jpdb-reader-newtab-prompt-anki-card .jpdb-reader-anki-study-card {
  width: 100%;
  max-width: 100%;
  min-width: 0;
  margin: 0 auto;
  align-content: center;
  justify-items: center;
  text-align: center;
}

.jpdb-reader-newtab-prompt-anki-card .jpdb-reader-anki-rendered-card,
.jpdb-reader-newtab-prompt-anki-card .jpdb-reader-anki-rendered-side {
  width: 100%;
  min-width: 0;
  align-content: center;
  justify-items: center;
}

.jpdb-reader-newtab-prompt-anki-card
  .jpdb-reader-anki-rendered-side-body {
  width: min(100%, 680px);
  max-width: min(100%, 680px);
  min-width: 0;
  border-inline-start: 0;
  padding: 0;
  text-align: center;
  font-size: clamp(19px, 1.7vw, 26px);
  overflow-wrap: anywhere;
}

.jpdb-reader-newtab-prompt-anki-card
  .jpdb-reader-anki-rendered-side-body
  :where(*) {
  max-width: 100%;
  font-size: min(1em, 1.9rem) !important;
  line-height: 1.35 !important;
  overflow-wrap: anywhere;
}

.jpdb-reader-newtab-prompt-anki-card .jpdb-reader-anki-rendered-side-body img,
.jpdb-reader-newtab-prompt-anki-card .jpdb-reader-anki-rendered-side-body video,
.jpdb-reader-newtab-prompt-anki-card .jpdb-reader-anki-rendered-side-body canvas,
.jpdb-reader-newtab-prompt-anki-card .jpdb-reader-anki-rendered-side-body svg {
  max-width: min(100%, 340px) !important;
  max-height: min(42vh, 260px) !important;
  object-fit: contain;
}

.jpdb-reader-newtab-prompt-anki-card .jpdb-reader-anki-sound {
  justify-self: center;
  margin: 0 0.18em;
  vertical-align: middle;
}

.jpdb-reader-newtab-prompt-anki-card .jpdb-reader-anki-primary-sound {
  order: -1;
  align-self: center;
  justify-self: end;
  margin: 0 0 2px auto;
  background: var(--jpdb-reader-surface);
  color: var(--jpdb-reader-text);
}

.jpdb-reader-newtab-prompt-anki-card
  .jpdb-reader-anki-primary-sound
  svg {
  width: 20px !important;
  height: 20px !important;
  max-width: 20px !important;
  max-height: 20px !important;
}

.jpdb-reader-newtab-front {
  display: grid;
  justify-items: center;
  gap: clamp(10px, 1.8vh, 18px);
  width: 100%;
  min-width: 0;
  text-align: center;
}

/* The headword and its audio control sit together as one centered unit. */

.jpdb-reader-newtab-term-row {
  display: flex;
  flex-wrap: nowrap;
  align-items: center;
  justify-content: center;
  gap: clamp(8px, 1.4vw, 16px);
  width: 100%;
  min-width: 0;
}

.jpdb-reader-newtab-term {
  display: block;
  min-width: 0;
  max-width: 100%;
  font-size: inherit;
  line-height: inherit;
  overflow-wrap: anywhere;
  text-align: center;
}

/* Audio button inline beside the word: quiet, fixed-size, never shrinks, and
   nudged toward the kanji baseline since furigana adds height above the word. */

.jpdb-reader-newtab-term-audio.jpdb-reader-icon-btn {
  flex: 0 0 auto;
  align-self: center;
  transform: translateY(0.12em);
}

.jpdb-reader-newtab-term .jpdb-reader-word {
  --jpdb-reader-word-color-source: currentColor;
  --jpdb-reader-word-accessible-color: currentColor;
  --jpdb-reader-word-decoration-source: transparent;
  --jpdb-reader-word-underline: transparent;
  --jpdb-reader-word-highlight-source: transparent;
  --jpdb-reader-word-highlight-paint: transparent;
  --jpdb-reader-word-accessible-highlight: transparent;
  --jpdb-reader-word-highlight-shadow-source: none;
  padding: 0;
  background: transparent !important;
  background-image: none !important;
  box-shadow: none !important;
  border-radius: 0;
  color: inherit !important;
  -webkit-text-fill-color: currentColor !important;
  text-decoration-color: transparent !important;
  text-shadow: none;
}

.jpdb-reader-newtab-term .jpdb-reader-word:is(
  .jpdb-pitch-heiban,
  .jpdb-pitch-atamadaka,
  .jpdb-pitch-nakadaka,
  .jpdb-pitch-odaka
) {
  --jpdb-reader-word-decoration-source: var(
    --jpdb-reader-source-pitch-decoration,
    var(--jpdb-reader-pitch-color, transparent)
  );
  --jpdb-reader-word-underline: var(
    --jpdb-reader-word-decoration-source,
    transparent
  );
}

.jpdb-reader-newtab-term .jpdb-reader-word::after {
  border-block-end-color: var(--jpdb-reader-word-underline, transparent) !important;
}

.jpdb-reader-newtab-term ruby {
  ruby-position: over;
}

.jpdb-reader-newtab-term rt {
  font-size: 0.24em;
  font-weight: 760;
  line-height: 1;
}

.jpdb-reader-newtab-study-tools {
  width: min(640px, 100%);
  min-width: 0;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 7px 9px;
  color: var(--jpdb-reader-muted);
  font-family: var(--jpdb-reader-font);
  font-size: 12px;
  font-weight: 780;
  line-height: 1.2;
  text-align: start;
  text-shadow: none;
}

.jpdb-reader-newtab-study-tools:empty {
  display: none;
}

.jpdb-reader-newtab-study-tool-main,
.jpdb-reader-newtab-study-tools .jpdb-reader-card-tools,
.jpdb-reader-newtab-study-tools .jpdb-reader-meta,
.jpdb-reader-newtab-study-tools .jpdb-reader-word-pills {
  min-width: 0;
  display: inline-flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 6px;
}

.jpdb-reader-newtab-study-tools .jpdb-reader-word-pills :is(a, span),
.jpdb-reader-newtab-study-tools .jpdb-reader-frequency-pill {
  min-height: 24px;
  display: inline-flex;
  align-items: center;
}

.jpdb-reader-newtab-study-tools .jpdb-reader-pitch {
  max-width: min(38vw, 168px);
  min-width: 0;
  overflow: hidden;
}

.jpdb-reader-newtab-study-tools .jpdb-reader-pitch svg {
  max-width: 100%;
  height: auto;
}

.jpdb-reader-newtab-study-tools .jpdb-reader-icon-btn {
  width: 34px;
  min-width: 34px;
  height: 34px;
  min-height: 34px;
  border: 1px solid var(--jpdb-reader-border);
  border-radius: 8px;
  background: color-mix(
    in srgb,
    var(--jpdb-reader-surface-2) 78%,
    transparent
  );
  color: var(--jpdb-reader-newtab-study-text);
}

.jpdb-reader-newtab-study-tools .jpdb-reader-icon-btn svg {
  width: 16px;
  height: 16px;
}

.jpdb-reader-newtab-kanji-mode .jpdb-reader-newtab-prompt {
  font-family: inherit;
  font-size: clamp(2.4rem, 6.4vw, 4.8rem);
  line-height: 1.02;
}

.jpdb-reader-newtab-kanji-prompt {
  font-size: clamp(1.45rem, 4vw, 2.35rem);
  line-height: 1.12;
}

.jpdb-reader-newtab-recall-prompt {
  max-width: min(100%, 700px);
  color: var(--jpdb-reader-newtab-study-text);
  font-size: clamp(2rem, 5.8vw, 4.3rem);
  line-height: 1.08;
}

.jpdb-reader-newtab-recall-question {
  display: block;
  max-width: 100%;
  overflow-wrap: anywhere;
  text-wrap: balance;
}

.jpdb-reader-newtab-recall-cloze {
  display: grid;
  justify-items: center;
  gap: 10px;
}

.jpdb-reader-newtab-recall-cloze-sentence {
  display: block;
  max-width: min(100%, 760px);
  overflow-wrap: anywhere;
}

.jpdb-reader-newtab-recall-gap {
  display: inline-block;
  min-width: min(7ch, 34vw);
  height: 0.14em;
  margin: 0 0.16em;
  border-radius: 999px;
  background: currentColor;
  vertical-align: baseline;
  transform: translateY(-0.08em);
}

.jpdb-reader-newtab-recall-hint {
  color: var(--jpdb-reader-newtab-study-muted);
  font-size: clamp(0.95rem, 2.6vw, 1.25rem);
  font-weight: 780;
  line-height: 1.25;
}

.jpdb-reader-newtab-kanji-front-keywords {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  gap: 6px 12px;
  max-width: min(100%, 680px);
}

.jpdb-reader-newtab-kanji-front-keyword {
  display: inline-flex;
  max-width: min(100%, 20em);
  align-items: baseline;
  justify-content: center;
  gap: 7px;
  font-size: clamp(1.35rem, 3.7vw, 2.55rem);
  line-height: 1.04;
}

.jpdb-reader-newtab-kanji-front-keyword small {
  color: var(--jpdb-reader-muted);
  font-size: clamp(0.68rem, 1.7vw, 0.95rem);
  font-weight: 860;
  line-height: 1;
  letter-spacing: 0;
  text-transform: uppercase;
}

.jpdb-reader-newtab-kanji-front-keyword span {
  min-width: 0;
  overflow-wrap: anywhere;
}

.jpdb-reader-newtab-kanji-front-empty {
  max-width: min(100%, 26em);
  color: var(--jpdb-reader-muted);
  font-size: clamp(0.95rem, 2vw, 1.2rem);
  font-weight: 760;
  line-height: 1.32;
  text-wrap: balance;
}

/* "drink — ＿み物": the word-context lead line for a kanji-draw step. Meaning and
   blanked-kanji cloze sit on one row so the draw prompt is never ambiguous. */

.jpdb-reader-newtab-kanji-front-context {
  flex-basis: 100%;
  flex-wrap: wrap;
  gap: 6px 10px;
}

.jpdb-reader-newtab-kanji-front-cloze {
  font-size: clamp(1.35rem, 3.7vw, 2.4rem);
  font-weight: 760;
  letter-spacing: 0.04em;
}

/* Progressive-hint affordance (kanji-draw + recall): a muted, unobtrusive row
   with a small "Hint" button. Revealed tiers list label + value; nothing prints
   the full answer before the reveal. The kanji-draw panel lives inside the huge
   .jpdb-reader-newtab-kanji-prompt (h1) whose font-size the (0,1,1) reader-root
   `:where(button)` reset inherits into buttons — so hint font-sizes need a
   compound selector (≥ specificity 0,1,1) to win, and the panel resets to a
   sane base so items/small children don't inherit the 4.8rem prompt size. */

.jpdb-reader-newtab-study-hint {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 6px 12px;
  margin-top: clamp(6px, 1.4vh, 14px);
  font-size: 1rem;
  font-weight: 500;
}

.jpdb-reader-newtab-study .jpdb-reader-newtab-study-hint-item {
  display: inline-flex;
  align-items: baseline;
  gap: 5px;
  color: var(--jpdb-reader-newtab-study-muted, var(--jpdb-reader-muted));
  font-size: clamp(0.9rem, 2.2vw, 1.1rem);
}

.jpdb-reader-newtab-study .jpdb-reader-newtab-study-hint-item small {
  color: var(--jpdb-reader-muted);
  font-size: clamp(0.62rem, 1.6vw, 0.8rem);
  font-weight: 820;
  text-transform: uppercase;
  letter-spacing: 0.02em;
}

button.jpdb-reader-newtab-study-hint-btn {
  padding: 3px 12px;
  border: 1px solid
    color-mix(in srgb, var(--jpdb-reader-accent, currentColor) 42%, var(--jpdb-reader-border, currentColor));
  border-radius: 999px;
  background: color-mix(in srgb, var(--jpdb-reader-accent, currentColor) 8%, transparent);
  color: var(--jpdb-reader-accent-readable, var(--jpdb-reader-text, currentColor));
  font-size: clamp(0.8rem, 2vw, 0.95rem);
  font-weight: 720;
  line-height: 1.4;
  cursor: pointer;
  transition:
    background-color 0.16s ease,
    border-color 0.16s ease,
    color 0.16s ease,
    transform 0.12s ease;
}

button.jpdb-reader-newtab-study-hint-btn:hover,
button.jpdb-reader-newtab-study-hint-btn:focus-visible {
  border-color: var(--jpdb-reader-accent, currentColor);
  background: color-mix(in srgb, var(--jpdb-reader-accent, currentColor) 16%, transparent);
  outline: none;
}

button.jpdb-reader-newtab-study-hint-btn:active {
  transform: translateY(1px);
}

.jpdb-reader-newtab-study-hint-summary {
  margin-top: 6px;
  color: var(--jpdb-reader-muted);
  font-size: clamp(0.78rem, 1.9vw, 0.92rem);
  font-weight: 640;
}

.jpdb-reader-newtab-revealed.jpdb-reader-newtab-kanji-mode
  .jpdb-reader-newtab-prompt {
  font-size: clamp(3.5rem, 9vh, 5rem);
  margin-bottom: 4px;
}

.jpdb-reader-newtab-sentence {
  display: block;
  max-width: min(100%, 680px);
  color: var(--jpdb-reader-newtab-study-muted);
  font-size: clamp(1.05rem, 2.6vw, 1.8rem);
  font-weight: 760;
  line-height: 1.36;
  overflow-wrap: anywhere;
  text-wrap: balance;
  text-shadow: none;
}

.jpdb-reader-newtab-sentence .jpdb-reader-word {
  --jpdb-reader-word-underline-offset: 0.08em;
  padding: 0 0.08em;
  border-radius: 0.1em;
  color: inherit;
  text-underline-offset: 0.08em;
}

.jpdb-reader-newtab-sentence .jpdb-reader-example-target {
  padding: 0 0.08em;
  border-radius: 0.22em;
  background: var(
    --jpdb-reader-example-target-bg,
    var(--jpdb-reader-accent-soft)
  );
  box-shadow: inset 0 -0.16em 0
    var(--jpdb-reader-example-target-underline, color-mix(in srgb, var(--jpdb-reader-accent) 64%, transparent));
  -webkit-box-decoration-break: clone;
  box-decoration-break: clone;
}

.jpdb-reader-newtab-sentence mark.jpdb-reader-example-target {
  color: inherit;
}

/* Front of a study card: the target word's own furigana gives the reading
   away (user-reported). Hide it until reveal; other words keep theirs, which
   matches jpdb's Learn front. visibility (not display) keeps the line height
   stable across reveal. */

.jpdb-reader-newtab:not(.jpdb-reader-newtab-revealed)
  .jpdb-reader-newtab-sentence
  .jpdb-reader-example-target
  :is(.jpdb-reader-furi, rt) {
  visibility: hidden;
}

.jpdb-reader-newtab-answer {
  width: min(640px, 100%);
  min-height: clamp(68px, 11vh, 124px);
  max-width: min(640px, 100%);
  display: grid;
  align-content: start;
  justify-items: center;
  gap: 8px;
}

.jpdb-reader-newtab:not(.jpdb-reader-newtab-revealed):not(
    .jpdb-reader-newtab-kanji-mode
  ):not(
    .jpdb-reader-newtab-recall-mode
  )
  .jpdb-reader-newtab-answer {
  min-height: 0;
  opacity: 0;
  filter: blur(8px);
  transform: translateY(4px);
  pointer-events: none;
  visibility: hidden;
}

/* Type is a production step, not a hidden-answer Word front. Its form lives in
   the shared answer slot, so restore that slot while the type cloze is active. */

.jpdb-reader-newtab:not(.jpdb-reader-newtab-revealed)
  .jpdb-reader-newtab-study[data-newtab-study-step="type-word"]
  .jpdb-reader-newtab-answer {
  opacity: 1;
  filter: none;
  transform: none;
  pointer-events: auto;
  visibility: visible;
}

.jpdb-reader-newtab-recall-form {
  width: min(100%, 560px);
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 8px;
  align-items: center;
}

.jpdb-reader-newtab-type-form {
  width: min(100%, 620px);
  grid-template-columns: 44px minmax(0, 1fr) auto;
  gap: 8px;
}

.jpdb-reader-newtab-type-form .jpdb-reader-newtab-term-audio {
  width: 44px;
  min-width: 44px;
  height: 44px;
  min-height: 44px;
  margin: 0;
  border: 1px solid var(--jpdb-reader-border);
  border-radius: 8px;
  background: color-mix(in srgb, var(--jpdb-reader-surface) 86%, transparent);
  color: var(--jpdb-reader-text);
  transform: none;
}

.jpdb-reader-newtab-recall-input {
  width: 100%;
  min-width: 0;
  min-height: 50px;
  border: 1px solid var(--jpdb-reader-border);
  border-radius: 8px;
  padding: 8px 12px;
  background: color-mix(in srgb, var(--jpdb-reader-surface) 86%, transparent);
  color: var(--jpdb-reader-text);
  -webkit-text-fill-color: var(--jpdb-reader-text);
  caret-color: var(--jpdb-reader-accent);
  font: 760 clamp(1.125rem, 2.3vw, 1.5rem) / 1.2 var(--jpdb-reader-font);
  text-align: center;
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--jpdb-reader-white) 52%, transparent);
}

.jpdb-reader-newtab-recall-input::placeholder {
  color: var(--jpdb-reader-faint);
  -webkit-text-fill-color: var(--jpdb-reader-faint);
  opacity: 1;
}

.jpdb-reader-newtab-recall-input::selection {
  color: var(--jpdb-reader-selection-text);
  background: var(--jpdb-reader-selection-bg);
  -webkit-text-fill-color: var(--jpdb-reader-selection-text);
}

.jpdb-reader-newtab[data-study-surface="academy"]
  :is(.jpdb-reader-newtab-searchbox input, .jpdb-reader-newtab-recall-input)::selection {
  color: #fffdf5;
  background: #6d5149;
  -webkit-text-fill-color: #fffdf5;
}

.jpdb-reader-newtab-recall-input:focus-visible {
  outline: 2px solid var(--jpdb-reader-accent);
  outline-offset: 2px;
}

.jpdb-reader-newtab-type-input[readonly] {
  border-color: color-mix(in srgb, var(--jpdb-reader-state-known) 68%, var(--jpdb-reader-border));
  background: color-mix(in srgb, var(--jpdb-reader-state-known) 8%, var(--jpdb-reader-surface));
}

.jpdb-reader-newtab .jpdb-reader-newtab-recall-check {
  min-height: 50px;
  border: 1px solid color-mix(in srgb, var(--jpdb-reader-accent) 42%, var(--jpdb-reader-border));
  border-radius: 8px;
  padding: 0 14px;
  background: color-mix(in srgb, var(--jpdb-reader-accent-soft) 82%, var(--jpdb-reader-surface));
  color: var(--jpdb-reader-accent-readable, var(--jpdb-reader-text));
  font: 820 14px / 1 var(--jpdb-reader-font);
  white-space: nowrap;
}

.jpdb-reader-newtab-recall-result {
  min-height: 24px;
  color: var(--jpdb-reader-muted);
  font-size: 13px;
  font-weight: 820;
  line-height: 1.25;
}

.jpdb-reader-newtab-recall-result[data-newtab-recall-result="correct"],
.jpdb-reader-newtab-recall-result[data-newtab-recall-result="accepted"] {
  color: var(--jpdb-reader-state-known);
}

.jpdb-reader-newtab-recall-result[data-newtab-recall-result="incorrect"],
.jpdb-reader-newtab-recall-result[data-newtab-recall-result="empty"] {
  color: color-mix(in srgb, var(--jpdb-reader-state-failed) 58%, var(--jpdb-reader-text));
}

/* ----- Type-word: mode toggle, skip, handwriting track (reuses recall input/result) ----- */

.jpdb-reader-newtab-type-modes {
  display: inline-flex;
  gap: 4px;
  padding: 3px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--jpdb-reader-surface) 82%, transparent);
  border: 1px solid var(--jpdb-reader-border);
}

.jpdb-reader-newtab .jpdb-reader-newtab-type-mode {
  min-height: 40px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 16px;
  border: 1px solid transparent;
  border-radius: 999px;
  background: transparent;
  color: var(--jpdb-reader-muted);
  font: 820 13px / 1 var(--jpdb-reader-font);
  cursor: pointer;
}

.jpdb-reader-newtab .jpdb-reader-newtab-type-mode[data-active="true"] {
  border-color: color-mix(in srgb, var(--jpdb-reader-accent) 46%, transparent);
  background: color-mix(in srgb, var(--jpdb-reader-accent-soft) 82%, var(--jpdb-reader-surface));
  color: var(--jpdb-reader-accent-readable, var(--jpdb-reader-text));
}

.jpdb-reader-newtab .jpdb-reader-newtab-type-mode:disabled {
  cursor: not-allowed;
  opacity: 0.46;
}

.jpdb-reader-newtab-type-result[data-newtab-type-result="correct"],
.jpdb-reader-newtab-type-result[data-newtab-type-result="accepted"] {
  color: var(--jpdb-reader-state-known);
}

.jpdb-reader-newtab-type-result[data-newtab-type-result="incorrect"] {
  color: color-mix(in srgb, var(--jpdb-reader-state-failed) 58%, var(--jpdb-reader-text));
}

.jpdb-reader-newtab-type-secondary {
  width: min(100%, 620px);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.jpdb-reader-newtab .jpdb-reader-newtab-type-skip {
  min-height: 40px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 16px;
  border: 1px solid var(--jpdb-reader-border);
  border-radius: 8px;
  background: transparent;
  color: var(--jpdb-reader-muted);
  font: 820 13px / 1 var(--jpdb-reader-font);
  cursor: pointer;
}

@media (pointer: coarse) {
  .jpdb-reader-newtab .jpdb-reader-newtab-type-mode,
  .jpdb-reader-newtab .jpdb-reader-newtab-type-skip {
    min-height: 44px;
  }
}

@media (max-width: 520px) {
  .jpdb-reader-newtab-type-form {
    grid-template-columns: 44px minmax(0, 1fr);
  }

  .jpdb-reader-newtab-type-form .jpdb-reader-newtab-term-audio {
    width: 44px;
    min-width: 44px;
    height: 44px;
  }

  .jpdb-reader-newtab-type-form .jpdb-reader-newtab-recall-check {
    grid-column: 1 / -1;
    width: 100%;
  }

  .jpdb-reader-newtab-type-secondary {
    align-items: stretch;
    flex-direction: column;
  }

  .jpdb-reader-newtab-type-modes {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

.jpdb-reader-newtab-type-handwriting {
  display: grid;
  justify-items: center;
  gap: 8px;
}

.jpdb-reader-newtab-type-handwriting-track {
  display: inline-flex;
  gap: 6px;
  font: 900 clamp(1.4rem, 4vw, 2rem) / 1 var(--jpdb-reader-font);
}

.jpdb-reader-newtab-type-handwriting-cell {
  color: var(--jpdb-reader-muted);
}

.jpdb-reader-newtab-type-handwriting-cell[data-done="true"] {
  color: var(--jpdb-reader-state-known);
}

.jpdb-reader-newtab-type-handwriting-cell[data-fixed="true"] {
  color: var(--jpdb-reader-text);
}

.jpdb-reader-newtab-type-handwriting-cell[data-active="true"] {
  color: var(--jpdb-reader-accent);
}

.jpdb-reader-newtab-type-handwriting-prompt {
  color: var(--jpdb-reader-muted);
  font-size: 13px;
  font-weight: 820;
}

.jpdb-reader-newtab-type-self-check-answer {
  color: var(--jpdb-reader-newtab-study-text);
  font-size: clamp(2rem, 6vw, 4rem);
  font-weight: 900;
}

.jpdb-reader-newtab-type-self-check-actions,
[data-type-word-self-check-choices] {
  display: grid;
  justify-items: center;
  gap: 8px;
}

[data-type-word-self-check-choices][hidden] {
  display: none;
}

.jpdb-reader-newtab .jpdb-reader-newtab-type-self-check-choice {
  min-height: 44px;
  min-width: 180px;
  border: 1px solid var(--jpdb-reader-border);
  border-radius: 8px;
  padding: 0 16px;
  background: var(--jpdb-reader-surface);
  color: var(--jpdb-reader-text);
  font: 820 13px / 1 var(--jpdb-reader-font);
}

[data-newtab-action="grade"][data-suggested="true"] {
  outline: 2px solid var(--jpdb-reader-accent);
  outline-offset: 2px;
}

.jpdb-reader-newtab-recall-solution {
  width: 100%;
  display: grid;
  justify-items: center;
  color: var(--jpdb-reader-newtab-study-text);
  font-size: clamp(2.1rem, 6.2vw, 4.7rem);
  font-weight: 900;
  line-height: 1.06;
}

.jpdb-reader-newtab:not(.jpdb-reader-newtab-revealed)
  .jpdb-reader-newtab-answer:has(.jpdb-reader-newtab-kanji-front) {
  min-height: clamp(68px, 11vh, 124px);
  opacity: 1;
  filter: none;
  transform: none;
  pointer-events: auto;
  visibility: visible;
}

.jpdb-reader-newtab-answer:has(.jpdb-reader-newtab-kanji-answer) {
  width: 100%;
  max-width: 100%;
}

.jpdb-reader-newtab-reading {
  max-width: 100%;
  width: 100%;
  color: var(--jpdb-reader-newtab-study-text);
  font-size: clamp(1.2rem, 3.2vw, 2rem);
  font-weight: 780;
  line-height: 1.12;
  text-align: center;
  overflow-wrap: anywhere;
}

.jpdb-reader-newtab-reading:empty {
  display: none;
}

.jpdb-reader-newtab-reading .jpdb-reader-word {
  --jpdb-reader-word-underline: transparent;
  background: transparent !important;
  color: inherit;
  text-decoration-color: transparent !important;
}

.jpdb-reader-newtab-meaning {
  width: min(640px, 100%);
  max-width: min(640px, 100%);
  display: grid;
  justify-items: center;
  gap: 12px;
  color: var(--jpdb-reader-newtab-study-text);
  font-size: clamp(14px, 2.1vw, 18px);
  font-weight: 650;
  line-height: 1.42;
  text-align: center;
  overflow-wrap: anywhere;
  text-wrap: balance;
}

.jpdb-reader-newtab-controls {
  z-index: 20;
  justify-self: center;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(92px, 1fr));
  gap: 8px;
  width: min(680px, calc(100vw - 28px));
  margin: clamp(12px, 2.5vh, 28px) auto 0;
  padding: 8px;
}

.jpdb-reader-newtab-controls[data-newtab-control-count="2"]:not(.jpdb-reader-newtab-grade-controls) {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.jpdb-reader-newtab-controls[hidden],
.jpdb-reader-newtab-search-mode .jpdb-reader-newtab-controls {
  display: none !important;
}

.jpdb-reader-newtab-controls.jpdb-reader-newtab-grade-controls {
  position: fixed;
  left: 50%;
  bottom: max(12px, env(safe-area-inset-bottom));
  transform: translateX(-50%);
  margin: 0;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  width: min(860px, calc(100vw - 28px));
  justify-content: center;
  justify-items: stretch;
  align-items: center;
  overflow: visible;
  scrollbar-width: none;
}

.jpdb-reader-newtab-controls.jpdb-reader-newtab-grade-controls[data-newtab-grade-scale="pass-fail"],
.jpdb-reader-newtab-controls.jpdb-reader-newtab-grade-controls[data-newtab-grade-count="2"] {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  width: min(680px, calc(100vw - 28px));
  max-width: calc(100vw - 28px);
  gap: 10px;
}

.jpdb-reader-newtab-controls[data-newtab-grade-scale="pass-fail"] button[data-grade] {
  min-height: 54px;
  padding-inline: 14px;
  font-size: 15px;
}

.jpdb-reader-newtab-controls.jpdb-reader-newtab-grade-controls::-webkit-scrollbar {
  display: none;
}

.jpdb-reader-newtab-grade-help {
  position: absolute;
  left: 50%;
  bottom: calc(100% + 4px);
  width: min(720px, calc(100vw - 40px));
  margin: 0;
  padding: 6px 10px;
  transform: translateX(-50%);
  border: 1px solid rgba(139, 160, 177, 0.2);
  border-radius: 8px;
  background: color-mix(in srgb, var(--jpdb-reader-surface) 94%, transparent);
  color: var(--jpdb-reader-text-muted);
  font-size: 11px;
  line-height: 1.35;
  text-align: center;
  text-wrap: balance;
  box-shadow: 0 8px 24px rgba(7, 12, 18, 0.16);
}

.jpdb-reader-newtab-controls button {
  display: grid;
  place-items: center;
  width: 100%;
  min-height: 42px;
  padding: 0 12px;
  border: 1px solid
    rgba(139, 160, 177, 0.24);
  border-radius: 8px;
  background: linear-gradient(
    180deg,
    color-mix(in srgb, var(--jpdb-reader-surface-2) 82%, var(--jpdb-reader-bg) 18%),
    color-mix(in srgb, var(--jpdb-reader-surface) 90%, var(--jpdb-reader-bg) 10%)
  );
  color: var(--jpdb-reader-text);
  font-size: 13px;
  font-weight: 820;
  line-height: 1.05;
  text-align: center;
  text-wrap: balance;
  text-shadow: 0 1px 1px
    color-mix(in srgb, var(--jpdb-reader-black) 36%, transparent);
  cursor: pointer;
  transform: none;
  transition:
    background 0.14s ease,
    border-color 0.14s ease,
    box-shadow 0.14s ease,
    transform 0.12s ease;
  -webkit-tap-highlight-color: transparent;
}

.jpdb-reader-theme-light .jpdb-reader-newtab-controls button:not([data-grade]),
.yomu-page-theme-light .jpdb-reader-newtab-controls button:not([data-grade]) {
  border-color: color-mix(in srgb, var(--jpdb-reader-accent) 20%, var(--jpdb-reader-border));
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--jpdb-reader-white) 88%, var(--jpdb-reader-accent) 6%),
      color-mix(in srgb, var(--jpdb-reader-surface-2) 76%, var(--jpdb-reader-white) 24%)
    );
  color: var(--jpdb-reader-text);
  text-shadow: none;
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--jpdb-reader-white) 72%, transparent),
    0 5px 14px color-mix(in srgb, var(--jpdb-reader-accent) 8%, transparent);
}

.jpdb-reader-newtab-controls button[data-newtab-action="reveal"] {
  background: var(--jpdb-reader-text);
  border-color: var(--jpdb-reader-text);
  color: var(--jpdb-reader-bg);
}

.jpdb-reader-theme-light
  .jpdb-reader-newtab-controls
  button[data-newtab-action="reveal"],
.yomu-page-theme-light
  .jpdb-reader-newtab-controls
  button[data-newtab-action="reveal"] {
  border-color: color-mix(in srgb, var(--jpdb-reader-accent) 72%, var(--jpdb-reader-border));
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--jpdb-reader-accent) 94%, var(--jpdb-reader-white) 6%),
      var(--jpdb-reader-accent)
    );
  color: var(--jpdb-reader-accent-text, var(--jpdb-reader-white));
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--jpdb-reader-white) 26%, transparent),
    0 8px 20px color-mix(in srgb, var(--jpdb-reader-accent) 18%, transparent);
}

.jpdb-reader-newtab-grade-target {
  justify-self: center;
  position: relative;
  min-width: 0;
  max-width: 100%;
  color: var(--jpdb-reader-muted);
  font-size: 11px;
  font-weight: 720;
  line-height: 1.25;
  text-align: center;
}

.jpdb-reader-newtab-controls.jpdb-reader-newtab-grade-controls:has(
    .jpdb-reader-newtab-grade-target-context
  ) {
  position: relative;
  padding-top: 34px;
}

.jpdb-reader-newtab-controls.jpdb-reader-newtab-grade-controls:has(
    .jpdb-reader-newtab-grade-target-context[open]
  ) {
  padding-top: 104px;
}

.jpdb-reader-newtab-controls.jpdb-reader-newtab-grade-controls
  .jpdb-reader-newtab-grade-target-context {
  position: absolute;
  top: 2px;
  right: 8px;
  left: 8px;
  z-index: 22;
  display: grid;
  justify-items: center;
  max-width: none;
  color: var(--jpdb-reader-muted);
  font-size: 11px;
  font-weight: 780;
  line-height: 1.2;
  text-align: center;
  pointer-events: auto;
}

.jpdb-reader-newtab-grade-target-summary {
  width: 100%;
  min-height: 28px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: center;
  gap: 8px;
  list-style: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

.jpdb-reader-newtab-grade-target-summary::-webkit-details-marker {
  display: none;
}

.jpdb-reader-newtab-grade-target-summary::marker {
  content: "";
}

.jpdb-reader-newtab-grade-target-summary .jpdb-reader-mining-collapse {
  grid-column: 2;
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 72px;
  height: 28px;
  min-width: 72px;
  min-height: 28px;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: var(--jpdb-reader-muted);
  padding: 0;
  pointer-events: none;
}

