.jpdb-reader-newtab-composed-of {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  align-items: center;
  justify-content: center;
  margin-top: 10px;
}

.jpdb-reader-newtab-composed-of-label {
  color: var(--jpdb-reader-newtab-study-muted);
  font-size: 12px;
}

.jpdb-reader-newtab-composed-of-kanji {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 32px;
  padding: 2px 10px;
  border: 1px solid var(--jpdb-reader-border);
  border-radius: 999px;
  background: transparent;
  color: var(--jpdb-reader-newtab-study-text);
  font-size: 15px;
  cursor: pointer;
}

.jpdb-reader-newtab-composed-of-kanji small {
  color: var(--jpdb-reader-newtab-study-muted);
  font-size: 11px;
