  background: color-mix(in srgb, var(--jpdb-reader-accent) 18%, var(--jpdb-reader-surface)) !important;
  color: var(--jpdb-reader-text);
}

.jpdb-ocr-video-frame-resume-fallback {
  position: fixed;
  transform: translateX(-100%);
  z-index: 2147483644;
  display: inline-grid;
