    in srgb,
    var(--jpdb-ocr-auto-dark-surface) 54%,
    transparent
  );
  --jpdb-ocr-auto-dark-active: color-mix(
    in srgb,
    var(--jpdb-ocr-auto-dark-surface) 72%,
    transparent
  );
  --jpdb-ocr-auto-dark-border: color-mix(
    in srgb,
    var(--jpdb-reader-accent, #5ea780) 58%,
    rgba(255, 255, 255, 0.16)
  );
}

