  color: var(--jpdb-reader-accent);
}

.jpdb-reader-pitch-component-label {
  max-width: 128px;
  overflow: hidden;
  color: var(--jpdb-reader-muted);
  font-size: 10px;
  line-height: 1.2;
  text-overflow: ellipsis;
  white-space: nowrap;
}

