.jpdb-reader-audio-source-choice select {
  grid-column: 1;
  grid-row: 1;
}

.jpdb-reader-audio-source-choice .jpdb-reader-icon-mini {
  grid-column: 2;
  grid-row: 1;
}

.jpdb-reader-audio-source-choice > .jpdb-reader-control-text-mirror {
  grid-column: 1 / -1;
}

.jpdb-reader-audio-source-fields {
