.jpdb-subtitle-rail {
  position: absolute;
  z-index: 3;
  left: max(10px, env(safe-area-inset-left));
  right: auto;
  top: 10px;
  display: flex;
  align-items: center;
  justify-content: flex-start;
  align-content: flex-start;
  flex-wrap: wrap;
  gap: 4px;
  max-width: calc(100% - 20px);
  padding: 4px;
  border: 1px solid var(--jpdb-reader-border);
  border-radius: 8px;
  background: color-mix(in srgb, var(--jpdb-reader-surface) 82%, transparent);
  box-shadow: 0 12px 30px var(--jpdb-reader-shadow);
  backdrop-filter: blur(14px);
  pointer-events: auto;
  isolation: isolate;
  opacity: .78;
  transform: translateY(0);
  transition: opacity .16s ease, transform .16s ease;
}

/* The mobile web player (#player-control-overlay) puts autoplay/CC/settings
   in the top-right corner where the rail sits; the controller measures that
   row and hands us an inset so the rail clears it instead of covering it. */

.jpdb-subtitle-native-top-controls .jpdb-subtitle-rail {
  top: max(var(--jpdb-subtitle-native-top-inset, 56px), env(safe-area-inset-top));
}

.jpdb-subtitle-controls-hidden .jpdb-subtitle-rail {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transform: translateY(-4px);
}

.jpdb-subtitle-controls-auto .jpdb-subtitle-rail:not(:hover):not(:focus-within) { opacity: .72; }

.jpdb-subtitle-controls-auto.jpdb-subtitle-controls-idle:not(.jpdb-subtitle-style-open) .jpdb-subtitle-rail:not(:hover):not(:focus-within) {
  opacity: .55;
  pointer-events: auto;
  transform: translateY(0);
}

.jpdb-subtitle-controls-auto.jpdb-subtitle-controls-idle:not(.jpdb-subtitle-style-open) .jpdb-subtitle-rail:not(:hover):not(:focus-within) > :not(.jpdb-subtitle-rail-move) {
  display: none !important;
}

/* Player chrome faded out = the viewer is watching, not controlling: hide the
   rail entirely instead of leaving even the minimised grip over the video. */

.jpdb-subtitle-controls-auto.jpdb-subtitle-controls-away:not(.jpdb-subtitle-style-open) .jpdb-subtitle-rail:not(:hover):not(:focus-within) {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

.jpdb-subtitle-controls-always .jpdb-subtitle-rail {
  opacity: 1;
}

.jpdb-subtitle-rail:hover,
.jpdb-subtitle-style-open .jpdb-subtitle-rail {
  opacity: 1;
