    border-radius: 80% 20% 65% 35%;
    background: var(--academy-warm);
    content: "";
    pointer-events: none;
    animation: academy-petal-fall 9s linear infinite;
}

.academy-access-screen .academy-screen-veil::before {
    left: 68%;
}

.academy-access-screen .academy-screen-veil::after {
    left: 84%;
