        transform: translateX(-18px) rotate(-0.35deg);
    }
    to {
        opacity: 1;
        transform: translateX(0) rotate(0);
    }
}

@keyframes academy-petal-fall {
    0% {
        opacity: 0;
        transform: translate3d(0, -10px, 0) rotate(0deg);
    }
    12%, 78% {
        opacity: 0.72;
    }
    100% {
        opacity: 0;
        transform: translate3d(-70px, 104vh, 0) rotate(540deg);
    }
}

