    border-bottom: 1px solid rgba(255, 253, 245, 0.34);
}

.academy-placement-form .academy-target-band[hidden] {
    display: none;
}

.academy-placement-form:has(.academy-target-band:not([hidden])) .academy-placement-confidence {
    display: none;
}

.academy-placement-form .academy-target-band .academy-label {
    color: #fffdf5;
}

.academy-placement-form .academy-target-band .academy-input {
    min-height: 44px;
}

/* The band/confidence selects rendered OS dropdown chrome, breaking the
   Choice-slip grammar the rest of the mock uses (F029). Suppress native
   appearance and give them the same asymmetric choice-slip corners + a
   drawn chevron, scoped to placement only. */
.academy-placement-screen select.academy-input {
    appearance: none;
    -webkit-appearance: none;
    padding-right: 34px;
    border-radius: 3px 10px 3px 9px;
    /* .academy-input sets `background` as an !important shorthand, so the
       chevron + paper fill must be one !important shorthand too, or the
       longhand layers get reset by that rule. */
    background:
        linear-gradient(45deg, transparent 50%, #29271f 50%) calc(100% - 20px) center / 6px 6px no-repeat,
        linear-gradient(135deg, #29271f 50%, transparent 50%) calc(100% - 14px) center / 6px 6px no-repeat,
        linear-gradient(rgba(255, 253, 244, 0.96), rgba(244, 237, 218, 0.94)) !important;
}

.academy-placement-progress {
