.academy-placement-screen .academy-placement-stage,
.academy-placement-screen .academy-panel-content,
.academy-placement-screen .academy-placement-form,
.academy-placement-screen .academy-placement-assessment-host,
.academy-placement-result-screen .academy-panel-content,
.academy-placement-result-screen .academy-recommendation,
.academy-placement-result-screen .academy-score-grid,
.academy-placement-result-screen .academy-score {
    min-width: 0;
}

.academy-placement-screen .academy-title,
.academy-placement-screen .academy-lede,
.academy-placement-screen .academy-mock-passage,
.academy-placement-screen .academy-mock-option-copy,
.academy-placement-result-screen .academy-placement-evidence-note,
.academy-placement-result-screen .academy-placement-continuity-note,
.academy-placement-result-screen .academy-score-grid dt,
.academy-placement-result-screen .academy-recommendation-band {
