}

.academy-placement-screen .academy-mock-option-copy {
    min-width: 0;
}

.academy-placement-screen .academy-placement-actions {
    align-items: center;
    flex-wrap: wrap;
}

.academy-placement-actions > button {
    min-width: 0;
}

.academy-placement-screen .academy-placement-actions .academy-lesson-overview-back {
    display: inline-flex;
    min-width: 44px;
    min-height: 44px;
    align-items: center;
    justify-content: center;
    padding: 8px 10px;
    color: #fffdf5;
    border-bottom-color: currentColor;
    text-shadow: 0 2px 10px rgba(0, 0, 0, 0.72);
}

.academy-placement-screen .academy-placement-actions .academy-lesson-overview-back:hover,
.academy-placement-screen .academy-placement-actions .academy-lesson-overview-back:focus-visible {
    color: #fffdf5;
    background: color-mix(in srgb, #fffdf5 14%, transparent);
}

.academy-placement-screen :is(.academy-input, .academy-button, .academy-lesson-overview-back):focus-visible,
.academy-placement-result-screen :is(.academy-button, .academy-lesson-overview-back):focus-visible,
.academy-placement-screen .academy-mock-option:has(input:focus-visible) {
    outline: 3px solid var(--academy-accent-strong);
    outline-offset: 3px;
}

.academy-placement-screen .academy-placement-actions .academy-lesson-overview-back:focus-visible {
    outline-color: #fffdf5;
}

.academy-journal-screen .academy-panel {
    width: min(1120px, 100%);
    max-height: none;
    overflow: visible;
    padding: 0;
    border: 0;
    color: #fffdf5;
    background: transparent;
    box-shadow: none;
    backdrop-filter: none;
}

.academy-journal-screen .academy-panel::before,
.academy-journal-screen .academy-panel::after {
    display: none;
}

.academy-journal-screen .academy-title {
    width: fit-content;
    margin: 0;
    padding: 8px 14px 9px;
    color: #fffdf5;
    background: rgba(14, 17, 16, 0.78);
    box-shadow: 4px 5px 0 rgba(0, 0, 0, 0.26);
    text-shadow: 0 2px 8px rgba(0, 0, 0, 0.5);
    font-size: clamp(2rem, 4vw, 3.25rem);
}

@media (min-width: 521px) {
    .academy-journal-screen .academy-panel-content {
        display: grid;
        grid-template-columns: minmax(0, 1fr) auto;
        align-items: end;
        column-gap: 18px;
    }

    .academy-journal-screen .academy-title {
        grid-column: 1;
    }

    .academy-journal-screen .academy-journal-profile-sync {
        grid-column: 2;
        width: fit-content;
        min-width: 164px;
        min-height: 42px;
        justify-self: end;
        margin: 0 0 7px;
        padding: 9px 14px;
        border: 1px solid rgba(255, 253, 245, 0.46);
        border-left: 4px solid var(--academy-accent-strong);
        border-radius: 4px;
        color: #fffdf5;
        background: rgba(14, 17, 16, 0.78);
        box-shadow: 3px 4px 0 rgba(0, 0, 0, 0.24);
    }

    .academy-journal-screen .academy-character-directory,
    .academy-journal-screen .academy-character-page {
        grid-column: 1 / -1;
    }
}

.academy-journal-screen .academy-character-directory {
    row-gap: 58px;
    padding-top: 48px;
}

.academy-journal-screen .academy-character-entry {
    overflow: visible;
    animation: academy-character-arrive 420ms cubic-bezier(0.2, 0.75, 0.25, 1) both;
    animation-delay: calc(min(var(--academy-character-order, 0), 12) * 36ms);
}

.academy-journal-screen .academy-character-open {
    overflow: visible;
    isolation: isolate;
    transition: transform 160ms ease, filter 160ms ease;
}

.academy-journal-screen .academy-character-portrait {
    inset: auto 2px 58px;
    top: -30px;
    height: calc(100% - 28px);
    transform-origin: center bottom;
    transition: transform 180ms ease, filter 180ms ease;
}

.academy-journal-screen .academy-character-portrait {
    overflow: hidden;
}

.academy-journal-screen .academy-character-portrait img {
    scale: var(--academy-sprite-focus-scale, 1);
    translate: 0 var(--academy-sprite-focus-y, 0%);
    transform-origin: center top;
}

.academy-journal-learning-lines {
    display: grid;
    gap: 10px;
    margin-bottom: 18px;
    padding: clamp(14px, 2vw, 22px);
    border: 1px solid color-mix(in srgb, var(--academy-ink) 22%, transparent);
    background: color-mix(in srgb, var(--academy-paper) 94%, white);
    box-shadow: 5px 7px 0 rgba(28, 23, 16, 0.12);
}

.academy-journal-learning-lines h2,
.academy-journal-learning-line {
    margin: 0;
}

.academy-journal-learning-line {
    padding-left: 12px;
    border-left: 3px solid var(--academy-accent);
    line-height: 1.55;
}

.academy-journal-screen .academy-character-caption {
    position: relative;
    z-index: 2;
    display: grid;
    width: 100%;
    min-width: 0;
    min-height: 62px;
    align-content: center;
    align-self: end;
    padding: 9px 10px 8px;
    border-top: 1px solid rgba(83, 69, 47, 0.2);
    color: var(--academy-paper-ink);
    background:
        linear-gradient(92deg, rgba(255, 253, 244, 0.98), rgba(244, 237, 216, 0.96)),
        var(--academy-paper);
    box-shadow: 0 -5px 14px rgba(45, 36, 24, 0.08);
}

.academy-journal-screen .academy-character-open:not(:disabled):is(:hover, :focus-visible) {
    transform: translateY(-4px);
    filter: drop-shadow(0 10px 8px rgba(24, 18, 12, 0.18));
}

.academy-journal-screen .academy-character-open:not(:disabled):is(:hover, :focus-visible) .academy-character-portrait {
    transform: translateY(-5px) scale(1.025);
    filter: drop-shadow(0 15px 13px rgba(45, 36, 24, 0.24));
}

@keyframes academy-character-arrive {
    from {
        opacity: 0;
        transform: translateY(14px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@media (max-width: 520px) {
    .academy-journal-screen .academy-character-directory {
        row-gap: 50px;
        column-gap: 12px;
        padding-top: 44px;
    }

    .academy-journal-screen .academy-character-entry {
        min-height: 174px;
    }

    .academy-journal-screen .academy-character-portrait {
        top: -24px;
        bottom: 62px;
        width: calc(100% - 4px);
        height: calc(100% - 30px);
    }

    .academy-journal-screen .academy-character-caption {
        min-height: 66px;
        padding-inline: 8px;
    }

    .academy-journal-screen .academy-character-state {
        min-height: 0;
        overflow-wrap: anywhere;
    }
}

@media (prefers-reduced-motion: reduce) {
    .academy-journal-screen .academy-character-entry,
    .academy-journal-screen .academy-character-open,
    .academy-journal-screen .academy-character-portrait {
        animation: none;
        transition: none;
    }

    .academy-journal-screen .academy-character-open:not(:disabled):is(:hover, :focus-visible),
    .academy-journal-screen .academy-character-open:not(:disabled):is(:hover, :focus-visible) .academy-character-portrait {
        transform: none;
    }
}

@media (max-width: 700px) {
    .academy-screen > .academy-background[data-mobile-presentation='art-directed-crop'] img {
        object-position: var(--academy-mobile-object-position, center);
    }
}

.academy-placement-screen .academy-screen-veil,
.academy-source-screen .academy-screen-veil,
.academy-journal-screen .academy-screen-veil {
    align-items: start;
}

.academy-mock-item {
    display: grid;
    gap: 12px;
    min-width: 0;
    padding: 16px;
    border: 1px solid rgba(73, 63, 46, 0.24);
    min-height: 180px;
    /* Living-paper asymmetric corners (3-15px) instead of a uniform rounded
       card — see docs/academy/VISUAL-SYSTEM.md geometry rule (F031). */
    border-radius: 4px 15px 5px 11px;
    color: #29271f;
    color-scheme: light;
    background:
        linear-gradient(rgba(255, 253, 244, 0.96), rgba(244, 237, 218, 0.94)),
        repeating-linear-gradient(0deg, transparent 0 30px, rgba(78, 64, 41, 0.07) 31px 32px);
    box-shadow: 6px 8px 0 rgba(9, 12, 11, 0.22);
}

.academy-mock-item[hidden],
.academy-placement-confidence[hidden] {
    display: none;
}

.academy-mock-prompt {
    float: left;
    width: 100%;
    max-width: 100%;
    margin: 0 0 8px;
    padding: 0;
    overflow-wrap: anywhere;
    font-weight: 750;
    line-height: 1.55;
    text-wrap: pretty;
}

/* The task itself (choose the reading, pick the best answer) was only ever
   implicit in the prompt sentence, with no visible instruction (F118). A
   quiet paper-header label is enough without becoming tutorial copy. */
.academy-mock-instruction {
    margin: 0;
    color: var(--academy-ink-muted);
    font-size: 0.72rem;
    font-weight: 650;
    letter-spacing: 0.03em;
    text-transform: uppercase;
}

.academy-mock-prompt + * {
    clear: both;
}

.academy-mock-passage {
    margin: 0;
    padding: 12px;
    border-left: 3px solid var(--academy-accent);
    color: var(--academy-ink-muted);
    line-height: 1.65;
}

.academy-mock-options {
    display: grid;
    gap: 8px;
}

.academy-mock-option {
    display: flex;
    min-height: 44px;
    align-items: center;
    gap: 10px;
    padding: 8px 10px;
    /* Asymmetric choice-slip corners so four answers don't read as a uniform
       rounded-card wall (F031). */
    border-radius: 3px 10px 3px 9px;
    color: #29271f !important;
    background: rgba(255, 253, 244, 0.74);
    cursor: pointer;
    -webkit-text-fill-color: #29271f !important;
}

.academy-mock-option:has(input:checked) {
    outline: 2px solid var(--academy-accent);
    background: color-mix(in srgb, var(--academy-accent) 12%, var(--academy-paper));
}

.academy-placement-confidence {
    min-height: 180px;
    align-content: center;
    padding: 18px;
    border: 1px solid var(--academy-line);
    border-radius: 6px;
    background: rgba(255, 252, 241, 0.66);
}

.academy-placement-actions {
    display: flex;
    justify-content: flex-end;
    gap: 10px;
}

.academy-placement-actions [hidden] {
    display: none;
}

.academy-confidence-grid,
.academy-score-grid {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    gap: 14px;
}

.academy-score-grid {
    align-items: center;
    margin: 0;
}

.academy-score-grid dt {
    color: var(--academy-ink-muted);
}

.academy-score {
    display: grid;
    grid-template-columns: minmax(80px, 1fr) auto;
    align-items: center;
    gap: 10px;
    margin: 0;
}

.academy-score-meter {
    position: relative;
    height: 9px;
    overflow: hidden;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.1);
}

.academy-score-meter::after {
    position: absolute;
    inset: 0;
    width: calc(var(--academy-score) * 100%);
    border-radius: inherit;
    background: linear-gradient(90deg, var(--academy-accent), var(--academy-warm));
    content: "";
}

/* Self-reported confidence is not a graded measurement: no fill, no percent,
   a dashed outline standing in for the solid meter used by graded skills. */
.academy-score-meter-hollow {
    border: 1px dashed rgba(255, 255, 255, 0.38);
    background: transparent;
}

.academy-score-meter-hollow::after {
    display: none;
}

.academy-score-self-reported .academy-score-value {
    color: var(--academy-ink-muted);
    font-size: 0.78em;
    font-style: italic;
}

.academy-recommendation {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 14px;
    padding: 16px;
    border: 1px solid var(--academy-line-strong);
    border-radius: 16px;
    background: color-mix(in srgb, var(--academy-accent) 10%, transparent);
}

/* Placement is one Rie-led scene. Questions, briefing, production and result
   change the paper in the foreground without changing the stage beneath it. */
.academy-placement-result-screen .academy-screen-veil {
    align-items: end;
    padding: 28px clamp(24px, 5vw, 72px);
    background: linear-gradient(180deg, rgba(24, 27, 24, 0.04) 0%, rgba(24, 27, 24, 0.2) 44%, rgba(24, 27, 24, 0.72) 100%);
}

.academy-placement-result-screen .academy-placement-stage {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(230px, 31%);
    width: min(1120px, 100%);
    min-height: 430px;
    max-height: calc(100dvh - 56px);
    margin: 0 auto;
    padding: 0;
    overflow: visible;
    border: 0;
    color: #29271f;
    background: transparent;
    box-shadow: none;
    backdrop-filter: none;
}

.academy-placement-result-screen .academy-placement-stage::before,
.academy-placement-result-screen .academy-placement-stage::after {
    display: none;
}

.academy-placement-result-screen .academy-panel-content {
    position: relative;
    z-index: 2;
    grid-column: 1;
    grid-row: 1;
    align-self: end;
    min-width: 0;
    max-height: calc(100dvh - 80px);
    padding: 28px 30px 24px;
    overflow: auto;
    color: #29271f;
    background:
        repeating-linear-gradient(0deg, transparent 0 31px, rgba(78, 64, 41, 0.07) 32px 33px),
        linear-gradient(rgba(255, 253, 244, 0.985), rgba(244, 237, 218, 0.97)) !important;
    border-left: 5px solid var(--academy-accent);
    clip-path: polygon(0 0, 98% 0, 100% 5%, 100% 94%, 96% 100%, 1% 99%, 0 96%);
    filter: drop-shadow(9px 14px 0 rgba(9, 12, 11, 0.26));
    color-scheme: light;
}

.academy-placement-result-screen .academy-placement-guide {
    grid-column: 2;
    grid-row: 1;
}

.academy-placement-result-screen .academy-title {
    margin-bottom: 4px;
    color: #29271f;
    font-size: clamp(2rem, 4vw, 3.25rem);
}

.academy-placement-result-screen .academy-lede,
.academy-placement-result-screen .academy-score-grid dt,
.academy-placement-result-screen .academy-placement-evidence-note,
.academy-placement-result-screen .academy-placement-transcript-evidence-note,
.academy-placement-result-screen .academy-placement-continuity-note {
