    gap: 10px 16px;
    padding-block: 4px;
}

.academy-placement-result-screen .academy-score-grid dt {
    font-weight: 700;
    line-height: 1.25;
}

.academy-placement-result-screen .academy-score-value {
    color: #29271f;
    text-align: right;
}

.academy-placement-briefing,
.academy-placement-production {
