    box-shadow: 7px 9px 0 rgba(9, 12, 11, 0.24);
}

.academy-placement-briefing[hidden],
.academy-placement-production[hidden] {
    display: none;
}

.academy-placement-step-title,
.academy-placement-step-body,
.academy-placement-briefing-line,
.academy-placement-production-model,
.academy-placement-production-prompt,
.academy-placement-transcript-line,
.academy-placement-transcript-note,
.academy-placement-evidence-note,
.academy-placement-transcript-evidence-note,
.academy-placement-continuity-note {
