    border-radius: 0;
}

.academy-lesson-overview-screen .academy-lesson-overview-goals {
    padding-right: clamp(18px, 3vw, 34px);
    border-right: 1px solid rgb(73 63 46 / 20%);
}

.academy-lesson-overview-screen .academy-lesson-overview-sections {
    animation: academy-overview-rise 580ms 100ms cubic-bezier(.2, .75, .25, 1) both;
}

.academy-lesson-overview-screen .academy-lesson-overview-section {
    transition: background-color 180ms ease, transform 180ms ease;
}

.academy-lesson-overview-screen .academy-lesson-overview-section[aria-current="step"] {
    position: relative;
    background: linear-gradient(90deg, color-mix(in srgb, var(--academy-accent) 20%, transparent), transparent 84%);
    box-shadow: inset 4px 0 color-mix(in srgb, var(--academy-accent) 82%, transparent);
    animation: none;
}

.academy-lesson-overview-screen .academy-lesson-overview-section:focus-within {
    z-index: 1;
    transform: translateX(4px);
}

.academy-lesson-overview-screen .academy-lesson-overview-margin {
    width: 100%;
    padding: 14px 0 0 14px;
    border-top: 1px solid rgb(73 63 46 / 20%);
    border-left: 3px solid color-mix(in srgb, var(--academy-accent) 72%, transparent);
    background: transparent;
    box-shadow: none;
    backdrop-filter: none;
}

.academy-lesson-overview-screen .academy-lesson-overview-roster {
    align-self: center;
    min-width: 0;
    padding: 12px 4px 15px;
    border: 0;
    background: transparent;
    box-shadow: none;
    backdrop-filter: none;
}

.academy-lesson-overview-screen .academy-lesson-overview-roster-title {
    margin: 0 6px 10px;
    color: #fffdf5;
    font-size: .72rem;
    font-weight: 850;
    text-shadow: 0 2px 8px rgb(8 12 12 / 72%);
    text-transform: uppercase;
}

.academy-lesson-overview-screen .academy-lesson-overview-roster-list {
    display: grid;
    gap: 6px;
    margin: 0;
    padding: 0;
    list-style: none;
}

.academy-lesson-overview-screen .academy-lesson-overview-roster-member {
    display: grid;
    grid-template-columns: 48px minmax(0, 1fr);
    gap: 8px;
    align-items: center;
    min-height: 58px;
    opacity: 0;
    animation: academy-overview-roster-in 360ms calc(180ms + var(--academy-roster-order) * 55ms) ease-out forwards;
}

.academy-lesson-overview-screen .academy-lesson-overview-roster-portrait {
    display: block;
    align-self: end;
    width: 48px;
    height: 60px;
    border: 0;
    border-radius: 0;
    background: transparent;
    filter: drop-shadow(0 4px 4px rgb(12 16 15 / 28%));
}

.academy-lesson-overview-screen .academy-lesson-overview-roster-portrait img {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: contain;
    object-position: center bottom;
}

.academy-lesson-overview-screen .academy-lesson-overview-roster-member.is-name-only {
    grid-template-columns: 1fr;
    min-height: 34px;
    padding-left: 5px;
}

.academy-lesson-overview-screen .academy-lesson-overview-roster-name {
    min-width: 0;
    color: #fffdf5;
    overflow-wrap: anywhere;
    font-size: clamp(.74rem, 1.1vw, .88rem);
    font-weight: 760;
    text-shadow: 0 2px 8px rgb(8 12 12 / 72%);
}

.academy-lesson-overview-screen .academy-lesson-overview-note-body {
    color: var(--academy-paper-ink);
}

@keyframes academy-overview-arrive {
    from { opacity: 0; transform: translateY(14px); }
    to { opacity: 1; transform: translateY(0); }
}

@keyframes academy-overview-rise {
    from { opacity: 0; transform: translateY(10px); }
    to { opacity: 1; transform: translateY(0); }
}

@keyframes academy-overview-roster-in {
    from { opacity: 0; transform: translateX(10px); }
    to { opacity: 1; transform: translateX(0); }
}

@keyframes academy-overview-current {
    0%, 100% { box-shadow: inset 3px 0 color-mix(in srgb, var(--academy-accent) 62%, transparent); }
    50% { box-shadow: inset 6px 0 color-mix(in srgb, var(--academy-accent) 88%, transparent); }
}

@media (max-width: 980px) {
    .academy-lesson-overview-screen .academy-lesson-overview-scene {
        grid-template-columns: minmax(0, 1fr) 132px;
        align-items: start;
    }

    .academy-lesson-overview-screen .academy-lesson-overview-body {
        grid-template-columns: 1fr;
    }

    .academy-lesson-overview-screen .academy-lesson-overview-goals {
        padding: 0 0 22px;
        border-right: 0;
        border-bottom: 1px solid rgb(73 63 46 / 20%);
    }

    .academy-lesson-overview-screen .academy-lesson-overview-roster-member {
        grid-template-columns: 40px minmax(0, 1fr);
    }

    .academy-lesson-overview-screen .academy-lesson-overview-roster-portrait {
        width: 40px;
        height: 52px;
    }
}

@media (max-width: 620px) {
    .academy-screen.academy-lesson-overview-screen {
        padding: 58px 8px 16px;
    }

    .academy-lesson-overview-screen .academy-lesson-overview-scene {
        grid-template-columns: 1fr;
        gap: 10px;
    }

    .academy-lesson-overview-screen .academy-lesson-overview-paper {
        gap: 18px;
        padding: 20px 18px 26px;
        overflow: visible;
    }

    .academy-lesson-overview-screen .academy-lesson-overview-header {
        grid-template-columns: 1fr;
        padding: 18px;
    }

    .academy-lesson-overview-screen .academy-lesson-overview-progress {
        width: 100%;
    }

    .academy-lesson-overview-screen .academy-lesson-overview-title {
        font-size: 2.4rem;
    }

    .academy-lesson-overview-screen .academy-lesson-overview-section {
        grid-template-columns: minmax(0, 1fr) auto;
    }

    .academy-lesson-overview-screen .academy-lesson-overview-section-title {
        white-space: normal;
    }

    .academy-lesson-overview-screen .academy-lesson-overview-margin {
        width: 100%;
    }

    .academy-lesson-overview-screen .academy-lesson-overview-roster {
        grid-row: 2;
        padding: 10px 12px;
    }

    .academy-lesson-overview-screen .academy-lesson-overview-roster-list {
        grid-template-columns: repeat(4, minmax(0, 1fr));
        gap: 8px 5px;
    }

    .academy-lesson-overview-screen .academy-lesson-overview-roster-member {
        grid-template-columns: 1fr;
        gap: 3px;
        justify-items: center;
        text-align: center;
    }

    .academy-lesson-overview-screen .academy-lesson-overview-roster-portrait {
        width: 42px;
        height: 56px;
    }

    .academy-lesson-overview-screen .academy-lesson-overview-roster-name {
        width: 100%;
        font-size: .67rem;
    }
}

@media (prefers-reduced-motion: reduce) {
    .academy-lesson-overview-screen .academy-lesson-overview-paper,
    .academy-lesson-overview-screen .academy-lesson-overview-sections,
    .academy-lesson-overview-screen .academy-lesson-overview-roster-member,
    .academy-lesson-overview-screen .academy-lesson-overview-section[aria-current="step"] {
        opacity: 1;
        animation: none;
        transform: none;
    }

    .academy-lesson-overview-screen .academy-lesson-overview-section,
    .academy-lesson-overview-screen .academy-lesson-overview-section-action {
        transition: none;
    }

    .academy-lesson-overview-screen .academy-lesson-overview-section:focus-within {
        transform: none;
    }
}

.academy-authored-week-listening-player {
    margin: 14px 0;
}

.academy-authored-week-listening-player audio {
    display: block;
    width: min(100%, 560px);
}

.academy-authored-week-transcript {
    margin-top: 14px;
}

.academy-authored-week-transcript summary {
    cursor: pointer;
}

.academy-authored-week-transcript-lines {
    margin-top: 10px;
}

.academy-authored-week-transcript-line {
    margin: 0 0 6px;
}
.academy-campus-screen .academy-panel {
    --academy-ink: #f2f4f0;
    --academy-ink-muted: #bfc4bd;
    --academy-line: rgba(242, 244, 240, 0.14);
    --academy-line-strong: color-mix(in srgb, var(--academy-accent) 50%, transparent);
    width: min(1120px, 100%);
    min-height: calc(100dvh - clamp(118px, 13vw, 162px));
    max-height: none;
    overflow: visible;
    padding: 0;
    border: 0;
    background: transparent;
    box-shadow: none;
    backdrop-filter: none;
}

/* Story runtime */
.academy-story-screen {
    min-height: calc(100dvh - clamp(90px, 11vw, 132px));
    overflow: auto;
    color: #272b28;
    background:
        linear-gradient(90deg, rgba(75, 112, 92, 0.08), transparent 28%, rgba(184, 77, 61, 0.07)),
        #f7f3e8;
}

.academy-story-content {
    width: min(1040px, calc(100% - 32px));
    margin: 0 auto;
    padding: clamp(28px, 6vw, 70px) 0 48px;
}

.academy-story-header {
    max-width: 760px;
    padding-bottom: 24px;
    border-bottom: 1px solid rgba(39, 43, 40, 0.22);
}

.academy-story-kicker,
.academy-story-template-day {
    margin: 0 0 8px;
    color: #a43e36;
    font: 750 0.75rem/1.3 var(--academy-font);
    text-transform: uppercase;
}

.academy-story-title {
    margin: 0;
    color: #202522;
    font: 800 clamp(2rem, 6vw, 4.5rem)/1 var(--academy-font);
    letter-spacing: 0;
    overflow-wrap: anywhere;
}

.academy-story-disclaimer,
.academy-story-boundary,
.academy-story-location {
    max-width: 68ch;
    margin: 14px 0 0;
    line-height: 1.55;
}

.academy-story-boundary {
    padding-left: 12px;
    border-left: 3px solid #4b705c;
    color: #4a514c;
}

.academy-story-episode-list,
.academy-story-template-list {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(230px, 1fr));
    gap: 10px;
    margin: 28px 0;
    padding: 0;
    list-style: none;
}

.academy-story-episode-button {
    display: grid;
    width: 100%;
    min-height: 150px;
    align-content: start;
    gap: 8px;
    padding: 16px;
    border: 1px solid rgba(39, 43, 40, 0.24);
    border-radius: 4px;
    color: inherit;
    background: rgba(255, 255, 252, 0.72);
    text-align: left;
    cursor: pointer;
}

.academy-story-episode-button:hover,
.academy-story-episode-button:focus-visible {
    border-color: #a43e36;
    background: #fffdf7;
}

.academy-story-episode-number,
.academy-story-episode-stage {
    color: #626a64;
    font-size: 0.76rem;
    line-height: 1.4;
}

.academy-story-episode-title {
    font-size: 1.05rem;
}

.academy-story-prose {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: 18px;
    margin: 28px 0;
}

.academy-story-beat h2,
.academy-story-meta-section h2,
.academy-story-template-mode {
    margin: 0 0 8px;
    font-size: 0.92rem;
}

.academy-story-beat p,
.academy-story-template p {
    margin: 0;
    line-height: 1.6;
}

.academy-story-metadata {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 12px;
}

.academy-story-meta-section,
.academy-story-template {
    min-width: 0;
    padding: 16px;
    border: 1px solid rgba(39, 43, 40, 0.18);
    border-radius: 4px;
    background: rgba(255, 255, 252, 0.62);
}

.academy-story-art-brief {
    border-color: rgba(164, 62, 54, 0.45);
}

.academy-story-chip-list {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    margin: 0;
    padding: 0;
    list-style: none;
}

.academy-story-chip-list li {
    padding: 4px 7px;
    border: 1px solid rgba(75, 112, 92, 0.35);
    border-radius: 3px;
    background: rgba(75, 112, 92, 0.08);
    font-size: 0.78rem;
}

.academy-story-details {
    display: grid;
    grid-template-columns: minmax(70px, max-content) 1fr;
    gap: 7px 12px;
    margin: 0;
    line-height: 1.45;
}

.academy-story-details dt {
    color: #626a64;
    font-weight: 700;
}

.academy-story-details dd {
    min-width: 0;
    margin: 0;
    overflow-wrap: anywhere;
}

.academy-story-actions {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    margin-top: 28px;
}

.academy-story-template {
    min-height: 178px;
}

.academy-story-template-remix {
    margin-top: 10px !important;
    color: #4b705c;
    font-weight: 700;
}

.academy-story-authored-arc {
    width: min(1180px, calc(100% - 24px));
    max-width: none;
    padding-top: clamp(18px, 3vw, 36px);
}

.academy-story-authored-arc .academy-story-header {
    width: min(760px, 100%);
    margin-inline: auto;
}

.academy-story-scene-picker {
    width: min(760px, 100%);
    margin: 18px auto;
    color: #4a514c;
}

.academy-story-scene-picker-title {
    cursor: pointer;
    font-size: 0.88rem;
    font-weight: 760;
}

.academy-story-scene-list {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 8px;
    margin: 12px 0 0;
    padding: 0;
    list-style: none;
}

.academy-story-scene-button {
    display: grid;
    width: 100%;
    min-height: 62px;
    gap: 4px;
    padding: 9px 10px;
    border: 1px solid rgba(39, 43, 40, 0.24);
    border-radius: 4px;
    color: inherit;
    background: rgba(255, 253, 247, 0.74);
    text-align: left;
    cursor: pointer;
}

.academy-story-scene-button[aria-current='step'] {
    border-color: #4b705c;
    box-shadow: inset 3px 0 #4b705c;
}

.academy-story-scene-package {
    color: #a43e36;
    font-size: 0.7rem;
    font-weight: 760;
}

.academy-story-scene-goal {
    font-size: 0.78rem;
    line-height: 1.35;
}

.academy-story-vn-host {
    margin: 0 auto;
}

.academy-story-vn-host .academy-vn-stage {
    min-height: clamp(500px, 72dvh, 720px);
    border: 1px solid rgba(39, 43, 40, 0.25);
    box-shadow: 0 18px 42px rgba(30, 33, 29, 0.22);
}

.academy-story-vn-action {
    display: grid;
    gap: 12px;
}

.academy-story-vn-prompt {
    color: #29271f;
}

.academy-story-vn-prompt .academy-story-stage-direction {
    margin: 0;
    font-size: 0.94rem;
    line-height: 1.5;
}

.academy-story-vn-action .academy-story-choice,
.academy-story-vn-action .academy-story-activity-handoff {
    width: 100%;
    margin: 0;
}

.academy-story-vn-action .academy-story-choice-option {
    width: 100%;
    margin-top: 8px;
    text-align: left;
}

.academy-story-activity-handoff {
    display: grid;
    gap: 9px;
    padding: 12px;
    border: 1px solid rgba(75, 112, 92, 0.36);
    background: rgba(75, 112, 92, 0.08);
}

.academy-story-activity-handoff p {
    margin: 0;
}

.academy-story-activity-kind {
    color: #376d55;
    font-size: 0.78rem;
    font-weight: 760;
}

.academy-story-activity-context {
    font-size: 0.88rem;
    line-height: 1.42;
}

@media (max-width: 620px) {
    .academy-story-authored-arc {
        width: 100%;
        padding-inline: 0;
    }

    .academy-story-authored-arc .academy-story-header,
    .academy-story-scene-picker {
        width: min(100% - 20px, 760px);
    }

    .academy-story-vn-host .academy-vn-stage {
        min-height: calc(100dvh - 108px);
        border-inline: 0;
    }
}

@media (max-width: 620px) {
    .academy-story-content {
        width: min(100% - 20px, 1040px);
        padding-top: 22px;
    }

    .academy-story-title {
        font-size: 2.15rem;
    }

    .academy-story-metadata {
        grid-template-columns: 1fr;
    }

    .academy-story-actions .academy-button {
        flex: 1 1 140px;
        white-space: normal;
    }
}

.academy-campus-screen .academy-panel::before,
.academy-campus-screen .academy-panel::after {
    display: none;
}

/* Library: the room remains the primary surface; paper only gathers at the desk. */
.academy-library-screen,
.academy-library-introduction {
    --library-ink: #342b20;
    --library-muted: #675a4b;
    --library-paper: rgba(255, 250, 233, 0.92);
    --library-red: #a84936;
    --library-green: #3f6659;
    min-height: 100dvh;
    overflow: hidden;
    color: #fffdf5;
    isolation: isolate;
}

.academy-library-screen .academy-background,
.academy-library-introduction .academy-background {
    z-index: -2;
}

.academy-library-veil {
    position: absolute;
    z-index: -1;
    inset: 0;
    pointer-events: none;
    background: linear-gradient(90deg, rgba(14, 17, 18, 0.5), transparent 53%, rgba(14, 17, 18, 0.24));
}

.academy-library-place-header {
    position: absolute;
    top: max(84px, calc(env(safe-area-inset-top) + 72px));
    left: clamp(16px, 6vw, 88px);
    max-width: min(450px, calc(100vw - 32px));
    text-shadow: 0 2px 18px rgba(0, 0, 0, 0.72);
}

.academy-library-marker,
.academy-library-speaker {
    width: fit-content;
    margin: 0;
    padding: 4px 8px;
    color: #382e23;
    background: rgba(255, 250, 233, 0.9);
    box-shadow: 2px 3px 0 rgba(13, 14, 12, 0.28);
    font: 750 0.7rem/1.2 var(--academy-font);
}

.academy-library-title {
    margin: 8px 0 0;
    color: inherit;
    font: 800 clamp(2rem, 5vw, 4rem)/0.98 var(--academy-font);
    letter-spacing: 0;
}

.academy-library-moment {
    margin: 10px 0 0;
    color: rgba(255, 253, 245, 0.86);
    font-size: 0.82rem;
}

.academy-library-desk {
    position: absolute;
    right: clamp(16px, 6vw, 88px);
    bottom: max(20px, env(safe-area-inset-bottom));
    display: grid;
    gap: 10px;
    width: min(390px, calc(100vw - 32px));
    padding: 18px;
    border: 1px solid rgba(255, 250, 233, 0.44);
    border-radius: 4px 14px 6px 11px;
    color: var(--library-ink);
    background:
        linear-gradient(90deg, rgba(168, 73, 54, 0.08), transparent 34%),
        var(--library-paper);
    box-shadow: 5px 7px 0 rgba(12, 14, 13, 0.24);
    backdrop-filter: blur(12px);
}

.academy-library-note {
    margin: 0;
    color: #504538;
    font-size: 0.86rem;
    line-height: 1.45;
}

.academy-library-sheet-button,
.academy-library-back,
.academy-library-dialogue-continue,
.academy-vocabulary-sheet-close,
.academy-vocabulary-sheet-start,
.academy-vocabulary-sheet-audio {
    min-height: 40px;
    border: 1px solid rgba(53, 43, 32, 0.27);
    border-radius: 5px;
    color: #32291f;
    background: rgba(255, 253, 244, 0.9);
    cursor: pointer;
}

.academy-library-sheet-button,
.academy-library-back,
.academy-library-dialogue-continue,
.academy-vocabulary-sheet-close,
.academy-vocabulary-sheet-start {
    padding: 9px 12px;
    text-align: left;
}

.academy-library-sheet-button,
.academy-vocabulary-sheet-start,
.academy-library-dialogue-continue {
    border-color: var(--library-green);
    color: #fffdf5;
    background: var(--library-green);
    font-weight: 760;
}

.academy-library-back {
    width: fit-content;
    background: transparent;
}

.academy-library-sheet-button:hover,
.academy-library-dialogue-continue:hover,
.academy-vocabulary-sheet-start:hover {
    filter: brightness(1.12);
}

.academy-library-back:hover,
.academy-vocabulary-sheet-close:hover,
.academy-vocabulary-sheet-audio:hover {
    border-color: #a84936;
}

.academy-library-dialogue {
    position: absolute;
    right: clamp(16px, 7vw, 112px);
    bottom: max(18px, env(safe-area-inset-bottom));
    display: grid;
    grid-template-columns: minmax(130px, 220px) minmax(250px, 430px);
    align-items: end;
    max-width: calc(100vw - 32px);
    animation: academy-library-arrive 420ms ease-out both;
}

.academy-library-sensei {
    width: 100%;
    max-height: min(64vh, 520px);
    object-fit: contain;
    object-position: bottom center;
    filter: drop-shadow(0 14px 10px rgba(0, 0, 0, 0.32));
}

.academy-library-dialogue-paper {
    display: grid;
    gap: 12px;
    margin: 0 0 34px -18px;
    padding: 16px;
    border: 1px solid rgba(255, 250, 233, 0.5);
    border-radius: 5px 15px 4px 12px;
    color: var(--library-ink);
    background:
        linear-gradient(90deg, rgba(63, 102, 89, 0.09), transparent 40%),
        var(--library-paper);
    box-shadow: 5px 7px 0 rgba(11, 12, 10, 0.28);
    backdrop-filter: blur(12px);
}

.academy-library-dialogue-title {
