    box-shadow: 0 0 0 3px color-mix(in srgb, var(--academy-accent) 20%, transparent);
    content: "";
}

.academy-location:hover:not(:disabled) {
    border-color: var(--academy-accent-strong);
    background: color-mix(in srgb, var(--academy-accent) 10%, var(--academy-paper));
    transform: translateY(-2px) rotate(-0.3deg);
}

.academy-location:focus-visible {
    outline: 3px solid #fffdf5;
    outline-offset: 3px;
}

.academy-location:disabled {
    cursor: not-allowed;
    filter: saturate(0.3);
    opacity: 0.64;
}

.academy-location-purpose {
    color: var(--academy-paper-muted);
    font-size: 0.7rem;
    font-weight: 450;
    line-height: 1.35;
}

.academy-minimap {
    position: fixed;
    z-index: 32;
    top: max(70px, calc(env(safe-area-inset-top) + 64px));
    right: max(12px, env(safe-area-inset-right));
    display: grid;
    gap: 3px;
    min-width: 150px;
    max-width: min(260px, calc(100vw - 24px));
    padding: 7px 10px;
    border: 1px solid var(--academy-line);
    border-radius: 4px 12px 5px 9px;
    color: var(--academy-paper-ink);
    background: rgba(241, 234, 217, 0.9);
    box-shadow: 4px 5px 0 color-mix(in srgb, var(--academy-accent) 17%, transparent);
    backdrop-filter: blur(12px);
    pointer-events: none;
}

.academy-campus-screen .academy-minimap {
    display: none;
}

.academy-location-screen .academy-panel {
    background: rgba(255, 249, 230, 0.88);
}

.academy-location-screen .academy-place-marker {
    margin-bottom: -10px;
}

.academy-location-screen .academy-current-place-name {
    margin: 0;
    color: var(--academy-paper-ink);
    font-size: clamp(1.5rem, 4vw, 2.5rem);
}

.academy-minimap-label {
    color: var(--academy-paper-muted);
    font-size: 0.58rem;
}

.academy-minimap-route {
    display: flex;
    align-items: center;
    gap: 6px;
    overflow: hidden;
    font-size: 0.72rem;
    white-space: nowrap;
}

.academy-minimap-arrow {
    color: var(--academy-accent);
}

.academy-minimap-destination {
    overflow: hidden;
    color: var(--academy-accent-strong);
    text-overflow: ellipsis;
}

.academy-campus-screen[data-traveling] .academy-place-map {
    opacity: 0.38;
    transform: scale(1.035);
}

.academy-campus-screen[data-traveling] .academy-people-present {
    opacity: 0.5;
    transition: opacity 220ms ease;
}

.academy-campus-screen[data-traveling="classroom"] .academy-background img {
    transform: scale(1.08) translate(2%, 2%);
}

.academy-campus-screen[data-traveling="library"] .academy-background img {
    transform: scale(1.08) translate(-2%, 1%);
}

.academy-campus-screen[data-traveling="lab"] .academy-background img {
    transform: scale(1.07) translate(1%, -1%);
}

.academy-campus-screen[data-traveling="cafe"] .academy-background img {
    transform: scale(1.07) translate(-1%, -1%);
}

.academy-review-host {
    display: grid;
    gap: 16px;
}

.academy-lab-screen .academy-panel {
    width: min(820px, 100%);
}

.academy-lab-audio {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    align-items: center;
}

.academy-lab-timecode {
    color: var(--academy-ink-muted);
    font-size: 0.78rem;
}

.academy-lab-transcript,
.academy-lab-shadow {
    display: grid;
    gap: 10px;
    padding: 14px;
    border: 1px solid var(--academy-line);
    border-radius: 14px;
    background: rgba(255, 252, 241, 0.48);
}

.academy-lab-transcript[hidden],
.academy-lab-shadow[hidden] {
    display: none;
}

.academy-lab-transcript h2,
.academy-lab-shadow h2,
.academy-lab-shadow p {
    margin: 0;
}

.academy-lab-transcript h2,
.academy-lab-shadow h2 {
    font-size: 1rem;
}

.academy-lab-transcript > p[lang="ja"] {
    min-height: 2em;
    margin: 0;
    padding-top: 0.4em;
    color: var(--academy-accent-strong);
    font-size: clamp(1.35rem, 4vw, 2.4rem);
    line-height: 1.65;
}

.academy-review-expression {
    min-height: 2em;
    margin: 0;
    padding-top: 0.4em;
    font-size: clamp(1.8rem, 6vw, 4rem);
    line-height: 1.45;
}

.academy-review-answer {
    display: grid;
    gap: 10px;
    padding: 14px;
    border: 1px solid var(--academy-line);
    border-radius: 14px;
    background: rgba(255, 252, 241, 0.48);
}

.academy-review-answer[hidden] {
    display: none;
}

.academy-review-reading,
.academy-review-meaning {
    margin: 0;
    line-height: 1.55;
}

.academy-review-ratings {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 8px;
}

.academy-rating-button {
    min-height: 44px;
    border: 1px solid var(--academy-line);
    border-radius: 10px;
    color: var(--academy-ink);
    color: var(--academy-paper-ink);
    background: rgba(255, 252, 241, 0.62);
    cursor: pointer;
}

.academy-journal-profile {
    --academy-journal-portrait-height: clamp(330px, 42vw, 390px);

    position: relative;
    isolation: isolate;
    display: grid;
    grid-template-columns: minmax(230px, 39%) minmax(0, 1fr);
    gap: 18px;
    align-items: center;
    min-height: 286px;
    margin-block: 62px 16px;
    overflow: visible;
    padding: 16px;
    border: 1px solid var(--academy-line);
    border-radius: 6px 16px 8px 12px;
    background: rgba(255, 252, 241, 0.48);
    box-shadow: 3px 4px 0 rgba(83, 69, 47, 0.14);
}

.academy-journal-portrait {
    z-index: 1;
    align-self: end;
    justify-self: center;
    width: auto;
    height: var(--academy-journal-portrait-height);
    max-width: none;
    max-height: none;
    margin: -62px auto -20px -8px;
    object-fit: contain;
    object-position: center bottom;
    filter: drop-shadow(5px 8px 5px rgba(43, 35, 24, 0.2));
    pointer-events: none;
}

.academy-character-sprite-gallery {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    align-items: end;
    gap: 8px;
    width: 100%;
    min-width: 0;
    margin: 0;
}

.academy-character-sprite-gallery-image {
    display: block;
    width: 100%;
    min-width: 0;
    height: 100%;
    max-height: none;
    object-fit: contain;
    object-position: center bottom;
    filter: drop-shadow(0 10px 10px rgba(16, 18, 16, 0.2));
}

.academy-character-sprite-gallery-frame {
    display: grid;
    width: 100%;
    min-width: 0;
    height: clamp(230px, 34vw, 330px);
    max-height: 42dvh;
    overflow: hidden;
    place-items: end center;
}

.academy-character-sprite-gallery-frame .academy-character-sprite-gallery-image {
    scale: var(--academy-sprite-focus-scale, 1);
    translate: 0 var(--academy-sprite-focus-y, 0%);
    transform-origin: center top;
}

.academy-character-dossier-gallery {
    grid-template-columns: minmax(0, 1fr);
    align-items: start;
    width: min(780px, 100%);
    overflow: visible;
}

.academy-character-dossier-gallery .academy-journal-copy {
    z-index: 2;
    grid-row: 1;
    padding-right: 52px;
}

.academy-character-dossier-gallery .academy-character-sprite-gallery {
    grid-row: 2;
}

.academy-journal-rie {
    overflow: visible;
}

.academy-journal-rie .academy-journal-portrait {
    margin-left: -24px;
}

.academy-journal-rie .academy-journal-copy {
    position: relative;
    z-index: 2;
}

.academy-journal-aakash {
    overflow: visible;
}

.academy-journal-aakash .academy-journal-aakash-portrait {
    margin-left: -8px;
}

.academy-journal-aakash .academy-journal-copy {
    position: relative;
    z-index: 2;
}

.academy-journal-event-portrait {
    aspect-ratio: 4 / 3;
    object-fit: cover;
    object-position: 38% center;
}

.academy-journal-locked {
    margin: 0;
    padding: 18px;
    border: 1px dashed var(--academy-line);
    border-radius: 16px;
    color: var(--academy-ink-muted);
    background: rgba(255, 252, 241, 0.42);
}

.academy-journal-copy {
    display: grid;
    gap: 10px;
    min-width: 0;
}

.academy-journal-copy h2,
.academy-journal-copy p,
.academy-journal-copy blockquote {
    margin: 0;
}

.academy-journal-copy blockquote {
    color: var(--academy-ink-muted);
    line-height: 1.55;
}

.academy-character-directory {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(136px, 1fr));
    gap: 14px;
    margin: 34px 0 12px;
    padding-top: 22px;
    border-top: 1px solid rgba(255, 252, 241, 0.34);
}

.academy-character-entry {
    position: relative;
    display: grid;
    min-width: 0;
    min-height: 210px;
    align-content: end;
    overflow: hidden;
    padding: 14px 12px 12px;
    border: 1px solid rgba(83, 69, 47, 0.2);
    background:
        linear-gradient(168deg, transparent 0 72%, rgba(193, 84, 65, 0.08) 72.4% 73%, transparent 73.4%),
        repeating-linear-gradient(0deg, transparent 0 25px, rgba(90, 107, 88, 0.07) 26px),
        rgba(255, 252, 241, 0.9);
    box-shadow: 3px 5px 0 rgba(24, 18, 12, 0.18);
    clip-path: polygon(1% 1%, 98% 0, 100% 95%, 94% 100%, 0 98%);
}

.academy-character-open {
    position: absolute;
    inset: 0;
    display: grid;
    width: 100%;
    min-width: 0;
    align-content: end;
    padding: 14px 12px 12px;
    border: 0;
    color: inherit;
    background: transparent;
    text-align: left;
    cursor: pointer;
}

.academy-character-open:disabled {
    opacity: 1;
    cursor: default;
}

.academy-character-open:not(:disabled):hover,
.academy-character-open:not(:disabled):focus-visible {
    outline: 3px solid var(--academy-accent);
    outline-offset: -4px;
    background: rgba(255, 252, 241, 0.14);
}

.academy-character-entry[data-unlocked="false"]::before {
    content: "?";
    position: absolute;
    inset: 20px 12px 70px;
    display: grid;
    place-items: center;
    color: rgba(83, 69, 47, 0.25);
    font: 700 3rem/1 var(--academy-font);
    border: 1px dashed rgba(83, 69, 47, 0.22);
    pointer-events: none;
}

.academy-character-entry[data-unlocked="false"]::after {
    content: "";
    position: absolute;
    top: 8px;
    left: 50%;
    width: 54px;
    height: 14px;
    background: rgba(194, 213, 187, 0.62);
    transform: translateX(-50%) rotate(-2deg);
    pointer-events: none;
}

.academy-character-portrait {
    position: absolute;
    inset: 5px 2px 54px;
    width: calc(100% - 4px);
    height: calc(100% - 59px);
    object-fit: contain;
    object-position: center bottom;
    filter: drop-shadow(0 12px 12px rgba(45, 36, 24, 0.18));
    pointer-events: none;
}

.academy-character-portrait img {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: contain;
    object-position: center bottom;
}

.academy-character-name,
.academy-character-state {
    position: relative;
    z-index: 1;
    margin: 0;
}

.academy-character-page {
    min-height: 440px;
}

.academy-character-page[hidden],
.academy-character-directory[hidden] {
    display: none;
}

.academy-character-dossier {
    width: min(720px, 100%);
    margin: 48px 0 0;
    color: var(--academy-paper-ink);
    background: rgba(255, 252, 241, 0.94);
}

.academy-character-page-back {
    position: absolute;
    top: 12px;
    right: 12px;
    z-index: 3;
    left: auto;
}

.academy-character-name {
    color: var(--academy-paper-ink);
    font: 780 0.94rem/1.15 var(--academy-font);
}

.academy-character-state {
    min-height: 2.5em;
    margin-top: 4px;
    color: var(--academy-ink-muted);
    font: 600 0.7rem/1.25 var(--academy-font);
}

.academy-relationship-pages {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 5px 12px;
    margin: 0;
    padding: 10px 0;
    border-top: 1px solid var(--academy-line);
    border-bottom: 1px solid var(--academy-line);
    list-style: none;
}

.academy-relationship-page {
    display: flex;
    gap: 7px;
    align-items: baseline;
    color: var(--academy-ink-muted);
    font-size: 0.76rem;
}

.academy-relationship-page[data-unlocked="false"] {
    opacity: 0.38;
}

.academy-relationship-page[data-unlocked="true"] {
    color: var(--academy-paper-ink);
    font-weight: 700;
}

.academy-relationship-page-number {
    font-family: var(--academy-font);
    font-size: 0.7rem;
    letter-spacing: 0.08em;
}

@media (max-width: 700px) {
    .academy-place-map {
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 8px;
        min-height: 0;
        background: transparent;
    }

    .academy-campus-screen .academy-panel {
        min-height: calc(100dvh - 116px);
        padding: 0;
        border: 0;
        background: transparent;
        backdrop-filter: none;
    }

    .academy-current-place-header {
        margin-top: 0;
    }

    .academy-current-place-name {
        font-size: clamp(1.85rem, 9vw, 3rem);
    }

    .academy-people-present {
        right: -20px;
        bottom: 174px;
        height: min(42vh, 350px);
    }

    .academy-place-person {
        width: clamp(118px, 31vw, 178px);
        margin-right: -30px;
    }

    .academy-place-person-name {
        display: none;
    }

    .academy-exits-heading {
        bottom: 166px;
    }

    .academy-location {
        width: 100%;
        min-height: 62px;
        padding: 9px 22px 9px 10px;
    }

    .academy-location-purpose {
        font-size: 0.62rem;
    }

    .academy-minimap {
        top: max(62px, calc(env(safe-area-inset-top) + 56px));
        min-width: 0;
        max-width: calc(100vw - 24px);
    }

    .academy-review-ratings {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .academy-journal-profile {
        --academy-journal-portrait-height: clamp(292px, 48vw, 330px);

        grid-template-columns: minmax(158px, 38%) minmax(0, 1fr);
        gap: 12px;
        min-height: 250px;
        margin-block: 48px 14px;
        padding: 12px;
    }

    .academy-character-dossier-gallery {
        grid-template-columns: minmax(0, 1fr);
    }

    .academy-character-dossier-gallery .academy-character-sprite-gallery-frame {
        height: clamp(190px, 42vw, 260px);
        max-height: 34dvh;
    }

    .academy-journal-portrait {
        margin: -44px auto -16px -10px;
    }
}

