/* Class Journal: one finite, paged book over the classroom scene. */
.academy-journal-screen {
    min-height: 100dvh;
    overflow: hidden;
    isolation: isolate;
}

.academy-journal-screen .academy-background img {
    object-position: center;
    filter: saturate(0.92) brightness(0.7) contrast(1.04);
    transform: none;
}

.academy-journal-screen .academy-screen-veil {
    min-height: 100dvh;
    place-items: center;
    overflow: hidden;
    padding: max(74px, calc(env(safe-area-inset-top) + 62px)) clamp(14px, 3vw, 42px) max(14px, env(safe-area-inset-bottom));
    background:
        linear-gradient(90deg, rgba(9, 13, 12, 0.44), rgba(9, 13, 12, 0.14) 46%, rgba(9, 13, 12, 0.42)),
        linear-gradient(0deg, rgba(9, 13, 12, 0.34), transparent 55%);
}

.academy-journal-screen .academy-journal-book {
    width: min(1120px, 100%);
    height: min(760px, calc(100dvh - max(96px, calc(env(safe-area-inset-top) + 78px))));
    max-height: none;
    overflow: visible;
    padding: 0;
    border: 0;
    border-radius: 0;
    background: transparent;
    box-shadow: none;
    transform-origin: center bottom;
    animation: academy-journal-book-open 520ms cubic-bezier(0.18, 0.72, 0.24, 1) both;
    perspective: 1200px;
}

.academy-journal-screen .academy-journal-book::before {
    position: absolute;
    z-index: -1;
    inset: 9px -10px -11px 8px;
    border: 2px solid rgba(229, 189, 104, 0.72);
    background: #452d26;
    box-shadow: 0 26px 64px rgba(3, 7, 6, 0.48);
    clip-path: polygon(1% 2%, 99% 0, 100% 96%, 96% 100%, 2% 98%, 0 6%);
    content: '';
}

.academy-journal-screen .academy-journal-book::after {
    display: none;
}

.academy-journal-screen .academy-journal-book-content {
    position: relative;
    display: grid;
    grid-template:
        'title tabs' auto
        'intro tabs' auto
        'spread spread' minmax(0, 1fr)
        'footer footer' auto
        / minmax(0, 1fr) auto;
    gap: 7px 18px;
    height: 100%;
    overflow: hidden;
    padding: clamp(20px, 3vw, 34px) clamp(22px, 4vw, 52px) clamp(16px, 2vw, 24px);
    color: #29271f;
    background:
        linear-gradient(90deg, transparent 49.6%, rgba(94, 72, 43, 0.16) 49.9%, rgba(255, 255, 255, 0.2) 50.2%, transparent 50.55%),
        repeating-linear-gradient(0deg, transparent 0 29px, rgba(83, 105, 92, 0.075) 30px 31px),
        radial-gradient(circle at 17% 24%, rgba(118, 94, 56, 0.06) 0 1px, transparent 1.6px),
        #f3ecd9 !important;
    background-size: auto, auto, 23px 27px, auto !important;
    box-shadow: inset 0 0 30px rgba(96, 70, 38, 0.08);
    clip-path: polygon(1% 0, 48% 1%, 50% 0, 52% 1%, 99% 0, 100% 96%, 97% 100%, 52% 99%, 50% 100%, 48% 99%, 2% 100%, 0 94%);
}

.academy-journal-screen .academy-title {
    grid-area: title;
    max-width: none;
    margin: 0;
    padding-left: 13px;
    border-left: 6px solid #b94e4b;
    color: #29271f;
    background: transparent;
    box-shadow: none;
    text-shadow: none;
    font-size: clamp(1.8rem, 3.2vw, 3rem);
    letter-spacing: 0;
}

.academy-journal-book-intro {
    grid-area: intro;
    margin: 0;
    color: #615c50;
    font-size: 0.9rem;
    line-height: 1.4;
}

.academy-journal-book-controls {
    grid-area: tabs;
    display: flex;
    align-self: end;
    gap: 5px;
    align-items: center;
}

.academy-journal-book-tabs {
    display: flex;
    gap: 5px;
    align-items: center;
}

.academy-journal-book-tab,
.academy-journal-page-turn {
    min-height: 42px;
    padding: 7px 11px;
    border: 0;
    border-bottom: 3px solid transparent;
    color: #504a3f;
    background: transparent;
    font: 760 0.82rem/1.15 var(--academy-font);
    cursor: pointer;
}

.academy-journal-book-tab[aria-selected='true'] {
    border-bottom-color: #557862;
    color: #263c32;
    background: rgba(85, 120, 98, 0.08);
}

.academy-journal-book-tab:is(:hover, :focus-visible),
.academy-journal-page-turn:not(:disabled):is(:hover, :focus-visible) {
    outline: 2px solid #557862;
    outline-offset: 2px;
}

.academy-journal-screen .academy-character-directory,
.academy-journal-learning-lines,
.academy-journal-screen .academy-character-page {
    grid-area: spread;
    min-height: 0;
}

.academy-journal-screen .academy-character-directory {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    grid-template-rows: repeat(2, minmax(0, 1fr));
    gap: clamp(12px, 2vw, 24px);
    height: 100%;
    margin: 8px 0 0;
    padding: 20px 4px 5px;
    overflow: visible;
    border: 0;
}

.academy-journal-screen .academy-character-entry {
    min-height: 0;
    height: 100%;
    overflow: visible;
    animation: academy-journal-character-arrive 340ms calc(min(var(--academy-character-order), 5) * 45ms) ease-out both;
}

.academy-journal-screen [hidden] {
    display: none !important;
}

.academy-journal-learning-lines {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    grid-auto-rows: minmax(0, 1fr);
    gap: 14px 22px;
    align-content: stretch;
    height: 100%;
    padding: 20px 10px 8px;
}

.academy-journal-learning-lines h2 {
    grid-column: 1 / -1;
    align-self: end;
    margin: 0;
    padding-bottom: 6px;
    border-bottom: 2px solid #b94e4b;
    font-size: clamp(1.2rem, 2vw, 1.7rem);
}

.academy-journal-learning-line,
.academy-journal-learning-empty {
    min-width: 0;
    margin: 0;
    padding: 16px 18px;
    border-left: 5px solid #557862;
    color: #39362f;
    background: rgba(255, 252, 241, 0.46);
    font-size: clamp(0.9rem, 1.5vw, 1.05rem);
    line-height: 1.5;
}

.academy-journal-book-footer {
    grid-area: footer;
    display: grid;
    grid-template-columns: 1fr auto 1fr;
    gap: 10px;
    align-items: center;
    min-height: 44px;
    border-top: 1px solid rgba(55, 49, 37, 0.18);
}

.academy-journal-page-previous { justify-self: start; }
.academy-journal-page-next { justify-self: end; }
.academy-journal-page-turn:disabled { visibility: hidden; }
.academy-journal-page-indicator {
    color: #6b6354;
    font: 740 0.78rem/1 var(--academy-font);
}

.academy-journal-screen .academy-journal-profile-sync {
    position: static;
    width: fit-content;
    min-height: 38px;
    margin-left: 8px;
    padding: 7px 10px;
    border-radius: 3px;
    color: #263c32;
    background: rgba(85, 120, 98, 0.1);
    box-shadow: none;
}

.academy-journal-screen .academy-character-page {
    align-self: stretch;
    height: 100%;
    overflow: visible;
}

.academy-journal-screen .academy-character-dossier {
    display: grid;
    grid-template:
        'copy back' auto
        'gallery gallery' auto
        / minmax(0, 1fr) auto;
    gap: clamp(10px, 2vh, 18px) 18px;
    align-content: start;
    width: min(920px, 100%);
    height: calc(100% - 18px);
    max-height: 100%;
    margin: 18px auto 0;
    border: 0;
    background: transparent;
    box-shadow: none;
}

.academy-journal-screen .academy-character-dossier .academy-journal-copy {
    grid-area: copy;
    min-width: 0;
    padding-right: 0;
}

.academy-journal-screen .academy-character-dossier .academy-character-page-back {
    position: static;
    grid-area: back;
    align-self: start;
    justify-self: end;
    white-space: nowrap;
}

.academy-journal-screen .academy-character-dossier .academy-character-sprite-gallery,
.academy-journal-screen .academy-character-dossier > .academy-journal-portrait {
    grid-area: gallery;
    align-self: start;
    min-height: 0;
}

.academy-journal-screen .academy-character-dossier .academy-character-sprite-gallery-frame {
    height: min(31dvh, 300px);
}

@keyframes academy-journal-book-open {
    from { opacity: 0; transform: translateY(24px) rotateX(-7deg) scale(0.96); }
    to { opacity: 1; transform: translateY(0) rotateX(0) scale(1); }
}

@keyframes academy-journal-character-arrive {
    from { opacity: 0; transform: translateY(12px); }
    to { opacity: 1; transform: translateY(0); }
}

