@keyframes academy-courtyard-gate-in {
    from { filter: saturate(0.78) contrast(1.02) brightness(0.58); transform: scale(1.025); }
    to { filter: saturate(1.02) contrast(1.05) brightness(0.86); transform: scale(1); }
}

@keyframes academy-courtyard-canopy-in {
    from { opacity: 0; translate: -3% -5%; }
    to { opacity: 1; translate: 0 0; }
}

@keyframes academy-courtyard-petal-drift {
    0% { opacity: 0; translate: -8px -12px; rotate: -12deg; }
    14%, 78% { opacity: 0.92; }
    100% { opacity: 0; translate: 28px 52px; rotate: 34deg; }
}

@keyframes academy-courtyard-path-in {
    from { opacity: 0; translate: 0 8%; }
    to { opacity: 1; translate: 0 0; }
}

@keyframes academy-courtyard-notice-in {
    from { opacity: 0; translate: 10% 8%; }
    to { opacity: 1; translate: 0 0; }
}

@keyframes academy-courtyard-rie-in {
    from { opacity: 0; translate: 18px 12px; }
    to { opacity: 1; translate: 0 0; }
}

@keyframes academy-courtyard-aakash-in {
    from { opacity: 0; translate: -18px 12px; }
    to { opacity: 1; translate: 0 0; }
}

@keyframes academy-courtyard-journal-in {
    from { opacity: 0; translate: 14px 18px; }
    to { opacity: 1; translate: 0 0; }
}

@keyframes academy-courtyard-thread-draw {
    from { opacity: 0; scale: 0 1; }
    to { opacity: 1; scale: 1; }
}

@keyframes academy-courtyard-notebook-in {
    from { opacity: 0; translate: -10px -8px; }
    to { opacity: 1; translate: 0 0; }
}

@keyframes academy-courtyard-bell-ring {
    0%, 58%, 100% { rotate: 0deg; }
