/* Hosts map engine frames to these finite, semantic data attributes. */
[data-vn-performer] {
    --academy-vn-performance-lift: 0px;
    filter: grayscale(0.56) saturate(0.68) brightness(0.88);
    transition: filter 180ms ease, transform 180ms ease;
}

[data-vn-performer][data-performance-presence='active'] {
    filter: grayscale(0) saturate(1) brightness(1);
    transform: translateY(calc(-1 * var(--academy-vn-performance-lift)));
}

[data-vn-performer][data-performance-motion='entrance'] {
    animation: academy-vn-performance-entrance var(--academy-vn-performance-duration, 360ms) ease-out
        var(--academy-vn-performance-delay, 0ms) 1 both;
}

[data-vn-performer][data-performance-motion='jump'] {
    animation: academy-vn-performance-jump var(--academy-vn-performance-duration, 300ms) ease-out 0ms 1 both;
}

[data-vn-performer][data-performance-pose-transition='dissolve'] [data-vn-pose-layer] {
    animation: academy-vn-performance-pose-dissolve var(--academy-vn-pose-duration, 220ms) ease-out 1 both;
}

[data-vn-performer][data-performance-pose-transition='shift'] [data-vn-pose-layer] {
    animation: academy-vn-performance-pose-shift var(--academy-vn-pose-duration, 220ms) ease-out 1 both;
}

[data-vn-scene-transition='dissolve'] [data-vn-scene-layer] {
    animation: academy-vn-performance-scene-dissolve var(--academy-vn-scene-duration, 420ms) ease 1 both;
}

[data-vn-scene-transition='travel-left'] [data-vn-scene-layer] {
    animation: academy-vn-performance-scene-left var(--academy-vn-scene-duration, 420ms) ease-out 1 both;
}

[data-vn-scene-transition='travel-right'] [data-vn-scene-layer] {
    animation: academy-vn-performance-scene-right var(--academy-vn-scene-duration, 420ms) ease-out 1 both;
}

[data-vn-scene-transition='paper-reveal'] [data-vn-scene-layer] {
    animation: academy-vn-performance-scene-paper var(--academy-vn-scene-duration, 420ms)
        cubic-bezier(0.2, 0.72, 0.2, 1) 1 both;
}

[data-vn-scene-transition='ink-reveal'] [data-vn-scene-layer] {
    animation: academy-vn-performance-scene-ink var(--academy-vn-scene-duration, 420ms) ease-out 1 both;
}

[data-vn-camera-transition='pan-left'] [data-vn-camera-layer] {
    animation: academy-vn-performance-camera-left var(--academy-vn-camera-duration, 480ms) ease-out 1 both;
}

[data-vn-camera-transition='pan-right'] [data-vn-camera-layer] {
    animation: academy-vn-performance-camera-right var(--academy-vn-camera-duration, 480ms) ease-out 1 both;
}

[data-vn-camera-transition='push-in'] [data-vn-camera-layer] {
    animation: academy-vn-performance-camera-push var(--academy-vn-camera-duration, 480ms) ease-out 1 both;
}

[data-vn-camera-transition='pull-back'] [data-vn-camera-layer] {
    animation: academy-vn-performance-camera-pull var(--academy-vn-camera-duration, 480ms) ease-out 1 both;
}

[data-vn-camera-transition='tilt-left'] [data-vn-camera-layer] {
    animation: academy-vn-performance-camera-tilt-left var(--academy-vn-camera-duration, 480ms) ease-out 1 both;
}

[data-vn-camera-transition='tilt-right'] [data-vn-camera-layer] {
    animation: academy-vn-performance-camera-tilt-right var(--academy-vn-camera-duration, 480ms) ease-out 1 both;
}

@keyframes academy-vn-performance-entrance {
    from { opacity: 0; transform: translateY(24px); }
    to { opacity: 1; transform: translateY(calc(-1 * var(--academy-vn-performance-lift))); }
}

@keyframes academy-vn-performance-jump {
    0%, 100% { transform: translateY(calc(-1 * var(--academy-vn-performance-lift))); }
    42% { transform: translateY(calc(-1 * var(--academy-vn-performance-lift) - 16px)); }
}

@keyframes academy-vn-performance-pose-dissolve {
    from { opacity: 0.7; }
    to { opacity: 1; }
}

@keyframes academy-vn-performance-pose-shift {
    from { opacity: 0.74; transform: translateY(6px); }
    to { opacity: 1; transform: none; }
}

@keyframes academy-vn-performance-scene-dissolve {
    from { opacity: 0.68; }
    to { opacity: 1; }
}

@keyframes academy-vn-performance-scene-left {
    from { opacity: 0.72; transform: translateX(18px) scale(1.015); }
}

@keyframes academy-vn-performance-scene-right {
    from { opacity: 0.72; transform: translateX(-18px) scale(1.015); }
}

@keyframes academy-vn-performance-scene-paper {
    from { opacity: 0.74; clip-path: inset(0 0 100% 0); }
    to { opacity: 1; clip-path: inset(0); }
}

@keyframes academy-vn-performance-scene-ink {
    from { opacity: 0.48; filter: grayscale(0.82) contrast(0.86); transform: scale(1.012); }
    to { opacity: 1; filter: none; transform: none; }
}

@keyframes academy-vn-performance-camera-left {
    from { transform: translateX(12px); }
}

@keyframes academy-vn-performance-camera-right {
    from { transform: translateX(-12px); }
}

@keyframes academy-vn-performance-camera-push {
    from { transform: scale(0.985); }
}

@keyframes academy-vn-performance-camera-pull {
    from { transform: scale(1.02); }
}

@keyframes academy-vn-performance-camera-tilt-left {
    from { transform: rotate(1.2deg) scale(1.01); }
}

@keyframes academy-vn-performance-camera-tilt-right {
    from { transform: rotate(-1.2deg) scale(1.01); }
}

@media (max-width: 700px) {
    [data-vn-camera-transition] [data-vn-camera-layer] {
        animation: none;
    }

    [data-vn-scene-transition='travel-left'] [data-vn-scene-layer],
    [data-vn-scene-transition='travel-right'] [data-vn-scene-layer],
    [data-vn-scene-transition='paper-reveal'] [data-vn-scene-layer],
    [data-vn-scene-transition='ink-reveal'] [data-vn-scene-layer] {
        animation-name: academy-vn-performance-scene-dissolve;
    }
}

@media (prefers-reduced-motion: reduce) {
    [data-vn-performer],
    [data-vn-performer] [data-vn-pose-layer],
    [data-vn-scene-transition] [data-vn-scene-layer],
    [data-vn-camera-transition] [data-vn-camera-layer] {
        animation: none;
        transition: none;
        transform: none;
    }

    [data-vn-scene-presentation='paper-reveal'] [data-vn-scene-layer] {
        clip-path: none;
        filter: saturate(0.96) contrast(1.02);
    }

    [data-vn-scene-presentation='ink-reveal'] [data-vn-scene-layer] {
        filter: saturate(0.92) contrast(1.04);
    }
}
.academy-vn-stage {
    --academy-vn-focus-x: 50%;
    --academy-vn-focus-y: 50%;
    --academy-vn-parallax-x: 0;
    --academy-vn-parallax-y: 0;
    --academy-vn-paper: #f1ead9;
    --academy-vn-paper-deep: #ddd0b7;
    --academy-vn-paper-ink: #29271f;
    --academy-vn-paper-muted: #655f51;
    position: relative;
    isolation: isolate;
    width: 100%;
    min-width: 0;
    min-height: 100vh;
    min-height: 100dvh;
    overflow: hidden;
    color: var(--academy-vn-paper-ink);
    color-scheme: light only;
    background: #28251f;
    --bg: var(--academy-vn-paper);
    --surface: var(--academy-vn-paper);
    --surface-2: var(--academy-vn-paper-deep);
    --ink: var(--academy-vn-paper-ink);
    --muted: var(--academy-vn-paper-muted);
    --jpdb-reader-bg: var(--academy-vn-paper-deep);
    --jpdb-reader-surface: var(--academy-vn-paper);
    --jpdb-reader-surface-2: var(--academy-vn-paper-deep);
    --jpdb-reader-text: var(--academy-vn-paper-ink);
    --jpdb-reader-muted: var(--academy-vn-paper-muted);
}

.academy-vn-plate,
.academy-vn-atmosphere,
.academy-vn-cast {
    position: absolute;
    inset: 0;
}

.academy-vn-plate {
    z-index: 0;
    overflow: hidden;
    background: #28251f;
}

.academy-vn-plate img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: var(--academy-vn-focus-x) var(--academy-vn-focus-y);
    filter: saturate(1.08) brightness(1.06);
    transform: scale(1.025) translate3d(
        calc(var(--academy-vn-parallax-x) * -4px),
        calc(var(--academy-vn-parallax-y) * -3px),
        0
    );
    transition: opacity 260ms ease, transform 460ms cubic-bezier(0.2, 0.75, 0.2, 1);
}

.academy-vn-atmosphere {
    z-index: 1;
    pointer-events: none;
    background:
        linear-gradient(180deg, rgba(24, 21, 16, 0.02) 0%, rgba(24, 21, 16, 0.08) 54%, rgba(24, 21, 16, 0.48) 100%),
        radial-gradient(circle at 50% 38%, transparent 0 42%, rgba(19, 17, 14, 0.12) 100%);
    transform: translate3d(
        calc(var(--academy-vn-parallax-x) * -1px),
        calc(var(--academy-vn-parallax-y) * -1px),
        0
    );
}

.academy-vn-stage[data-transition="dissolve"] .academy-vn-plate img {
    animation: academy-vn-dissolve 320ms ease both;
}

.academy-vn-stage[data-transition="travel-left"] .academy-vn-plate img {
    animation: academy-vn-travel-left 420ms cubic-bezier(0.2, 0.72, 0.2, 1) both;
}

.academy-vn-stage[data-transition="travel-right"] .academy-vn-plate img {
    animation: academy-vn-travel-right 420ms cubic-bezier(0.2, 0.72, 0.2, 1) both;
}

.academy-vn-cast {
    z-index: 2;
    pointer-events: none;
}

.academy-vn-sprite-slot {
    --academy-vn-slot-x: 0px;
    position: absolute;
    left: 50%;
    bottom: clamp(116px, 17vh, 190px);
    width: min(43vw, 590px);
    height: min(78vh, 880px);
    opacity: 0.86;
    filter: grayscale(0.72) saturate(0.58) brightness(0.82);
    translate: calc(-50% + var(--academy-vn-slot-x)) 0;
    transform: translate3d(
        calc(var(--academy-vn-parallax-x) * 3px),
        calc(var(--academy-vn-parallax-y) * 2px - var(--academy-vn-performance-lift, 0px)),
        0
    ) scale(0.985);
    transform-origin: bottom center;
    transition:
        opacity 220ms ease,
        filter 220ms ease,
        transform 280ms cubic-bezier(0.2, 0.75, 0.2, 1),
        translate var(--academy-vn-pose-duration, 220ms) cubic-bezier(0.2, 0.75, 0.2, 1);
}

.academy-vn-sprite-slot[data-position="left"] {
    --academy-vn-slot-x: -26vw;
}

.academy-vn-sprite-slot[data-position="center"] {
    --academy-vn-slot-x: 0px;
}

.academy-vn-sprite-slot[data-position="right"] {
    --academy-vn-slot-x: 26vw;
}

.academy-vn-sprite-slot[data-position] {
    left: 50%;
    right: auto;
}

.academy-vn-sprite-slot[data-performance-presence="active"] {
    z-index: 2;
    opacity: 1;
    filter: saturate(1.06) brightness(1.04);
    transform: translate3d(
        calc(var(--academy-vn-parallax-x) * 4px),
        calc(var(--academy-vn-parallax-y) * 2px - var(--academy-vn-performance-lift, 0px)),
        0
    ) scale(1.015);
}

.academy-vn-sprite,
.academy-vn-sprite img,
.academy-vn-portrait-outgoing,
.academy-vn-portrait-outgoing img {
    display: block;
    width: 100%;
    height: 100%;
}

.academy-vn-sprite {
    position: relative;
    z-index: 1;
}

.academy-vn-sprite {
    overflow: hidden;
}

.academy-vn-sprite img,
.academy-vn-portrait-outgoing img {
    object-fit: contain;
    object-position: bottom center;
}

.academy-vn-sprite img {
    scale: var(--academy-sprite-focus-scale, 1);
    translate: 0 var(--academy-sprite-focus-y, 0%);
    transform-origin: center top;
}

.academy-vn-portrait-outgoing {
    position: absolute;
    z-index: 2;
    inset: 0;
    pointer-events: none;
    animation: academy-vn-portrait-swap-out var(--academy-vn-pose-duration, 220ms) ease both;
}

.academy-vn-object-slot {
    position: absolute;
    z-index: 4;
    left: 50%;
    bottom: clamp(176px, 26vh, 286px);
    width: min(60vw, 720px);
    max-height: 54vh;
    transform: translate3d(
        calc(-50% + var(--academy-vn-parallax-x) * 2px),
        calc(var(--academy-vn-parallax-y) * 1px),
        0
    );
    filter: drop-shadow(0 18px 22px rgba(20, 17, 12, 0.26));
}

.academy-vn-object-slot[data-empty="true"] {
    display: none;
}

.academy-vn-dialogue {
    position: absolute;
    z-index: 6;
    right: clamp(12px, 5vw, 74px);
    bottom: clamp(14px, 3.5vh, 44px);
    left: clamp(12px, 5vw, 74px);
    width: min(900px, calc(100% - clamp(24px, 10vw, 148px)));
    display: grid;
    grid-template-rows: auto minmax(0, 1fr);
    gap: 8px;
    min-height: clamp(130px, 19vh, 188px);
    max-height: min(62dvh, 680px);
    margin-inline: auto;
    padding: clamp(16px, 2.2vw, 24px) clamp(22px, 4vw, 50px) clamp(18px, 2.5vw, 30px);
    border: 1px solid rgba(70, 60, 43, 0.5);
    overflow: visible;
    color: var(--academy-vn-paper-ink);
    background:
        radial-gradient(circle at 18% 24%, rgba(111, 88, 52, 0.07) 0 1px, transparent 1.5px),
        color-mix(in srgb, var(--academy-vn-paper) 94%, transparent);
    background-size: 19px 23px, auto;
    box-shadow: 8px 10px 0 rgba(21, 18, 13, 0.34), 0 20px 44px rgba(16, 14, 11, 0.24);
