    border: 1px solid rgba(229, 220, 196, 0.18);
    background:
        repeating-linear-gradient(112deg, transparent 0 13px, rgba(232, 222, 195, 0.045) 14px 15px),
        color-mix(in srgb, #283d3a 78%, #262733);
    box-shadow:
        inset 0 -18px 0 rgba(10, 12, 18, 0.14),
