    grid-template-columns: minmax(150px, 0.42fr) minmax(300px, 0.9fr) minmax(300px, 0.78fr);
    align-items: center;
    gap: 20px;
    min-height: min(650px, calc(100dvh - 150px));
}

.academy-classroom-instruction-teach-portrait {
