    .academy-greeting-progress {
        grid-column: 1;
        grid-row: 2;
        max-width: none;
        padding: 3px 0 0;
        border-left: 0;
        color: var(--academy-accent-strong);
        background: transparent;
        font-size: 0.74rem;
        text-align: left;
    }

    .academy-greeting-body {
        min-height: calc(100dvh - 92px);
        padding: 18px 12px 0;
    }

    .academy-greeting-welcome,
    .academy-greeting-arrange,
    .academy-greeting-rehearse,
    .academy-greeting-complete {
        position: relative;
        display: block;
        min-width: 0;
        padding-top: 148px;
    }

    .academy-greeting-welcome-portrait,
    .academy-greeting-arrange-portrait,
    .academy-greeting-rehearse-portrait,
    .academy-greeting-complete-portrait {
        position: absolute;
        top: 0;
        right: 4px;
        z-index: 1;
        width: 180px;
        height: 210px;
        object-position: top center;
        opacity: 0.94;
    }

    .academy-greeting-paper {
        padding: 36px 22px 28px;
        background:
            linear-gradient(90deg, transparent 0 30px, color-mix(in srgb, var(--academy-accent) 22%, transparent) 31px 33px, transparent 34px),
            repeating-linear-gradient(180deg, transparent 0 35px, rgba(69, 67, 56, 0.12) 36px 37px),
            var(--academy-paper);
        box-shadow: 8px 11px 0 color-mix(in srgb, var(--academy-night) 48%, transparent), 0 18px 38px rgba(0, 0, 0, 0.25);
        clip-path: polygon(0 0, 96% 0, 100% 4%, 100% 96%, 95% 100%, 1% 99%, 0 95%);
    }

    .academy-greeting-paperclip {
        right: 22px;
    }

    .academy-greeting-dialogue,
    .academy-greeting-section-title,
    .academy-greeting-complete-title {
        font-size: 1.45rem;
    }

    .academy-greeting-selected-rail,
    .academy-greeting-phrase-bank {
        grid-template-columns: 1fr;
    }

    .academy-greeting-selected-rail {
        grid-template-columns: 1fr 1fr;
    }

    .academy-greeting-mode {
        grid-template-columns: 1fr;
        gap: 4px;
    }

    .academy-greeting-action {
        width: 100%;
        min-width: 0;
    }

    .academy-greeting-action-quiet {
        width: auto;
    }

    .academy-greeting-live {
        margin-inline: 16px;
        text-align: left;
    }
}

@media (max-width: 380px) {
    .academy-greeting-body {
        padding-inline: 8px;
    }

    .academy-greeting-paper {
        padding-inline: 18px;
    }

    .academy-greeting-selected-rail {
        grid-template-columns: 1fr;
    }

    .academy-greeting-phrase-japanese {
        font-size: 0.96rem;
    }
}

@media (prefers-reduced-motion: no-preference) {
    .academy-greeting-paper {
        animation: academy-greeting-paper-arrive 360ms ease-out both;
    }

    .academy-greeting-welcome-portrait,
    .academy-greeting-arrange-portrait,
    .academy-greeting-rehearse-portrait,
    .academy-greeting-complete-portrait {
        animation: academy-greeting-rie-arrive 420ms ease-out both;
    }
}

@keyframes academy-greeting-paper-arrive {
    from { opacity: 0; transform: translateY(18px) rotate(0.4deg); }
    to { opacity: 1; transform: translateY(0) rotate(0); }
}

@keyframes academy-greeting-rie-arrive {
    from { opacity: 0; transform: translateY(14px); }
    to { opacity: 1; transform: translateY(0); }
}
.academy-hiragana-screen {
    --academy-scene-background-x: 0px;
    --academy-scene-background-y: 0px;
    --academy-scene-foreground-x: 0px;
    --academy-scene-foreground-y: 0px;
    --academy-scene-paper-x: 0px;
    --academy-scene-paper-y: 0px;
    position: relative;
    min-height: 100dvh;
    overflow-x: clip;
    color: var(--academy-paper);
    background: var(--academy-night);
}

.academy-root:has(.academy-hiragana-screen) .academy-header {
    display: none;
}

.academy-hiragana-screen > .academy-background,
.academy-hiragana-screen > .academy-background img {
    position: fixed;
    inset: 0;
    width: 100%;
    height: 100%;
}

.academy-hiragana-screen > .academy-background img {
    object-fit: cover;
    object-position: center 46%;
    filter: saturate(0.74) brightness(0.34) contrast(1.08);
    scale: 1.035;
    translate: var(--academy-scene-background-x) var(--academy-scene-background-y);
    transition: translate 160ms ease-out;
    will-change: translate;
}

.academy-hiragana-screen::before {
    position: fixed;
    inset: 0;
    z-index: 0;
    background:
        linear-gradient(90deg, rgba(8, 13, 12, 0.82), rgba(8, 13, 12, 0.16) 62%, rgba(8, 13, 12, 0.68)),
        linear-gradient(180deg, rgba(8, 13, 12, 0.18), rgba(8, 13, 12, 0.78));
    content: '';
    pointer-events: none;
}

.academy-hiragana-shell {
    position: relative;
    z-index: 1;
    width: min(1260px, calc(100% - 40px));
    min-height: 100dvh;
    margin-inline: auto;
    padding: max(18px, env(safe-area-inset-top)) 0 max(28px, env(safe-area-inset-bottom));
}

.academy-hiragana-header {
    display: grid;
    grid-template-columns: 48px minmax(0, 1fr) minmax(130px, 210px);
    align-items: center;
    gap: 16px;
    min-height: 70px;
    padding: 10px 18px;
    border-bottom: 2px solid color-mix(in srgb, var(--academy-accent) 76%, transparent);
    background: color-mix(in srgb, var(--academy-night) 90%, transparent);
}

.academy-hiragana-back {
    width: 48px;
    height: 48px;
    min-width: 48px;
    padding: 0;
    border: 2px solid color-mix(in srgb, var(--academy-paper) 58%, transparent);
    border-radius: 0;
    color: var(--academy-paper);
    background: color-mix(in srgb, var(--academy-night) 84%, transparent);
    font-size: 1.5rem;
}

.academy-hiragana-heading {
    display: flex;
    min-width: 0;
    align-items: baseline;
    gap: 16px;
}

.academy-hiragana-eyebrow,
.academy-hiragana-title,
.academy-hiragana-progress {
    margin: 0;
    letter-spacing: 0;
}

.academy-hiragana-eyebrow {
    flex: 0 0 auto;
    color: var(--academy-accent-strong);
    font-size: 0.75rem;
    font-weight: 850;
    text-transform: uppercase;
}

.academy-hiragana-title {
    overflow: hidden;
    color: var(--academy-paper);
    font-size: 1.55rem;
    line-height: 1.1;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.academy-hiragana-progress {
    padding: 8px 12px;
    border-left: 3px solid var(--academy-accent);
    background: color-mix(in srgb, var(--academy-night) 72%, transparent);
    font-size: 0.88rem;
    font-weight: 800;
    text-align: right;
}

.academy-hiragana-body {
    display: grid;
    min-height: calc(100dvh - 110px);
    align-items: end;
    padding-top: 24px;
}

.academy-hiragana-scene {
    display: grid;
    grid-template-columns: minmax(220px, 0.32fr) minmax(0, 0.68fr);
