        linear-gradient(90deg, transparent 0 45px, color-mix(in srgb, var(--academy-accent) 24%, transparent) 46px 48px, transparent 49px),
        repeating-linear-gradient(180deg, transparent 0 37px, rgba(69, 67, 56, 0.13) 38px 39px),
