    box-shadow: 16px 22px 0 color-mix(in srgb, var(--academy-night) 52%, transparent), var(--academy-shadow);
    clip-path: polygon(0 0, 97% 0, 100% 7%, 100% 94%, 96% 100%, 2% 99%, 0 94%);
