    font-family: var(--academy-japanese-font);
    font-size: clamp(1.2rem, 2.8vw, 1.8rem);
    font-weight: 850;
}

.academy-hiragana-prompt-anchor {
    align-self: center;
    justify-content: start;
}

.academy-hiragana-kana {
