    grid-template-columns: repeat(4, minmax(90px, 1fr));
    gap: 10px;
    margin-top: 24px;
}

.academy-hiragana-choice {
    min-height: 58px;
    border: 2px solid var(--academy-paper-ink);
    border-radius: 0;
    color: var(--academy-paper);
    background: var(--academy-paper-ink);
    font-size: 1.08rem;
    font-weight: 850;
    clip-path: polygon(0 0, 92% 0, 100% 50%, 92% 100%, 0 100%);
}

.academy-hiragana-choice:hover,
.academy-hiragana-choice:focus-visible {
    color: var(--academy-paper-ink);
    background: var(--academy-accent);
}

.academy-hiragana-mastery-map {
    display: grid;
    gap: 6px;
    margin-top: 20px;
    padding: 16px;
    border-left: 7px solid var(--academy-accent);
    background: color-mix(in srgb, var(--academy-paper-deep) 64%, transparent);
}

.academy-hiragana-mastery-column {
    font-family: var(--academy-japanese-font);
    font-size: clamp(1rem, 2.8vw, 1.55rem);
    font-weight: 800;
    word-spacing: 0.35em;
}

.academy-hiragana-recall-form {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 10px;
    margin-top: 20px;
}

.academy-hiragana-field-label {
    grid-column: 1 / -1;
    color: var(--academy-paper-muted);
    font-size: 0.78rem;
    font-weight: 800;
    text-transform: uppercase;
}

.academy-hiragana-input {
