    padding: 10px 14px;
    border: 0;
    border-bottom: 4px solid var(--academy-accent);
    border-radius: 0;
    color: var(--academy-paper-ink);
    background: color-mix(in srgb, var(--academy-paper-deep) 72%, var(--academy-paper));
    font: inherit;
    font-size: 1.2rem;
}

.academy-hiragana-action {
