.academy-hiragana-action-primary {
    color: var(--academy-night);
    background: var(--academy-accent);
}

.academy-hiragana-action-quiet {
    margin-left: 10px;
    color: var(--academy-paper);
    background: var(--academy-paper-ink);
}

.academy-hiragana-stamp {
    display: block;
    width: max-content;
    margin-top: 20px;
    padding: 8px 16px;
    border: 4px double var(--academy-accent-strong);
    color: var(--academy-accent-strong);
    font-size: 1.4rem;
    transform: rotate(-2deg);
}

.academy-hiragana-live {
    position: fixed;
    right: max(18px, env(safe-area-inset-right));
    bottom: max(16px, env(safe-area-inset-bottom));
    z-index: 3;
    max-width: min(38ch, calc(100% - 36px));
    padding: 8px 12px;
    color: var(--academy-paper);
    background: color-mix(in srgb, var(--academy-night) 90%, transparent);
    font-size: 0.86rem;
}

@media (min-width: 761px) and (max-width: 980px) {
    .academy-hiragana-shell {
        width: calc(100% - 24px);
    }

    .academy-hiragana-scene {
        grid-template-columns: 180px minmax(0, 1fr);
        gap: 16px;
    }

    .academy-hiragana-paper {
        padding-inline: 32px;
    }
}

@media (max-width: 760px) {
    .academy-hiragana-shell {
        width: 100%;
        padding: env(safe-area-inset-top) 0 env(safe-area-inset-bottom);
    }

    .academy-hiragana-header {
        grid-template-areas:
            'back heading'
            'back progress';
        grid-template-columns: 44px minmax(0, 1fr);
        grid-template-rows: auto auto;
        gap: 9px;
        row-gap: 1px;
        min-height: 64px;
        padding: 8px 10px;
    }

    .academy-hiragana-back {
        grid-area: back;
        width: 44px;
        height: 44px;
        min-width: 44px;
        align-self: center;
    }

    .academy-hiragana-heading {
        grid-area: heading;
        display: grid;
        grid-template-columns: auto minmax(0, 1fr);
        align-items: baseline;
        gap: 8px;
    }

    .academy-hiragana-eyebrow {
        font-size: 0.62rem;
    }

    .academy-hiragana-title {
        overflow: visible;
        margin: 0;
        font-size: 0.98rem;
        text-overflow: clip;
        white-space: normal;
    }

    .academy-hiragana-progress {
        grid-area: progress;
        max-width: none;
        padding: 1px 8px;
        font-size: 0.7rem;
