}

.academy-lesson-language-tool {
    display: grid;
    width: 34px;
    height: 34px;
    padding: 0;
    place-items: center;
    border: 1px solid color-mix(in srgb, var(--academy-accent) 42%, var(--academy-line));
    border-radius: 2px;
    color: var(--academy-ink);
    background: var(--academy-paper);
    font: 800 0.9rem/1 var(--academy-japanese-font, "Hiragino Sans", "Yu Gothic", sans-serif);
