.academy-lesson-teaching-title {
    font-size: 1.15rem;
    letter-spacing: 0;
}

.academy-lesson-teaching-guidance {
    max-width: 62ch;
    color: var(--academy-ink-muted);
    line-height: 1.5;
}

.academy-lesson-teaching-entries {
    display: grid;
    gap: 8px;
    max-height: min(38dvh, 340px);
    overflow: auto;
